/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,o,k,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:o,answer:o[k],explain:x});
const C=(w,s,d,en,zh,st,g,r)=>({senseId:`${w}.s${s}`,domain:d,en,zh,structure:st,grammar:g,rationale:r,sourceType:'authored'});
const M=(wrong,right,reason)=>({errorType:'meaning',wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase()}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[C(w,...c)],mistakes:[M(...m)],quiz:qs.map((q,i)=>Q(w,i+1,q[0],q[1],q[2],q[3],q[4]))});
P('grace','经古法语 grace 源自拉丁语 gratia“恩惠、优雅”，可指优美风度、宽限、恩惠，也可作动词表示增光。',[2,'社交礼仪','Even after the rude interruption, Mara answered with grace, thanking the speaker for the question and calmly returning to the discussion.','即使被粗鲁打断，玛拉仍有风度地致谢，并平静地回到讨论中。','Even after the rude interruption, / Mara answered with grace, / thanking the speaker for the question and calmly returning to the discussion.','s1 指动作优美；s2 指礼貌体面；s3 指恩惠或宽限；s4 作动词表示增光。','冷静礼貌地回应体现 grace s2 的风度与体面。'],['The host showed grace by insulting the guest, interrupting every sentence, and refusing to listen.','The host showed discourtesy by insulting the guest and refusing to listen.','侮辱并拒听他人表现粗鲁，不是 grace。'],[[1,'A dancer moves with grace when the movement is?',['smooth and attractive','stiff and awkward','unrelated to rhythm'],0,'grace s1 描述动作优美流畅。'],[2,'To accept a mistake with grace is to respond?',['politely and decently','with public insults','by refusing to acknowledge anyone'],0,'grace s2 指有礼貌、有风度。'],[3,'A grace period gives someone?',['extra time before a deadline or payment is enforced','a lower school grade','a new name'],0,'grace s3 可指额外宽限时间。'],[4,'“The portrait is graced by a bright window” means the window?',['adds beauty or distinction to it','makes it illegal','extends its deadline'],0,'grace 作动词 s4，表示使某物增色。']]);
P('grace period','由 grace 与 period 组成，指额外宽限的时间；也可比喻一段令人愉快、适应顺利的起始阶段。',[1,'账单支付','The insurer allowed a ten-day grace period after the premium due date, so the policy remained active while the customer arranged payment.','保险公司在保费到期日后给了十天宽限期，让客户安排付款期间保单仍然有效。','The insurer allowed a ten-day grace period after the premium due date, / so the policy remained active / while the customer arranged payment.','名词短语；常见 a grace period for payment/renewal，指截止期限后额外获准的时间。','客户在十天内补交保费而保单仍有效，符合 grace period。'],['The insurer cancelled the policy before its grace period began and offered no extra time for payment.','The insurer cancelled the policy after the grace period ended and offered no further time for payment.','若宽限期尚未开始，就不能说客户已在 grace period 内获得额外时间。'],[[1,'A ten-day grace period after a bill is due means?',['the payer has ten extra days under the stated terms','the bill was paid ten days early','the debt has been erased permanently'],0,'grace period 指截止后额外允许的时间。'],[1,'A new employee’s grace period may be?',['an initial adjustment period before full evaluation','a lifetime guarantee of promotion','a holiday with no work duties'],0,'引申义可指较顺利的适应起始阶段。'],[1,'Which phrase is natural?',['a grace period for renewal','a grace period at the invoice permanently','grace period to pay yesterday'],0,'常说 grace period for renewal/payment。'],[1,'Does a grace period normally change the original due date?',['It allows extra time after it under specified terms.','It proves the item was never due.','It means the obligation is cancelled in all cases.'],0,'宽限期通常是在规定到期点后额外准许的时段。']]);
P('graceful','由 grace 加形容词后缀 -ful 构成，表示动作优美流畅或行为得体。',[1,'舞蹈','The gymnast made a graceful landing, bending her knees smoothly and holding the final pose without wobbling.','体操运动员优雅落地，顺畅屈膝并稳稳保持最后的姿势。','The gymnast made a graceful landing, / bending her knees smoothly / and holding the final pose without wobbling.','形容词，常修饰 movement、gesture、landing；强调优美和协调。','平稳、连贯地落地展现 graceful movement。'],['The dancer’s graceful movement looked clumsy because she stumbled repeatedly and could not keep her balance.','The dancer’s awkward movement looked clumsy because she stumbled repeatedly and could not keep her balance.','反复绊倒、无法保持平衡是笨拙而非优雅。'],[[1,'A graceful movement is?',['smooth and attractive','abrupt and awkward','invisible to the audience'],0,'graceful 指动作优美协调。'],[1,'Which animal is moving gracefully?',['a swan glides smoothly across the pond','a cart jolts over every stone','a runner trips at each step'],0,'天鹅平稳滑行体现 graceful。'],[1,'Choose the natural collocation.',['a graceful gesture','graceful at the deadline','a graceful of the dancer'],0,'graceful 可修饰 gesture。'],[1,'A graceful speaker is likely to?',['behave with ease and poise','shout every word angrily','forget the audience is present'],0,'graceful 也可形容举止风雅从容。']]);
P('gracious','由 grace 加 -ious 构成，表示亲切有礼，也可指对地位较低者表现宽厚仁慈。',[1,'待客','Although the train was delayed, the host was gracious to the visiting team and found them a warm place to wait.','尽管火车晚点，主人仍亲切接待来访团队，为他们找了温暖的等候处。','Although the train was delayed, / the host was gracious to the visiting team / and found them a warm place to wait.','s1 指待人亲切有礼；s2 指居上位者宽厚对待他人。','安排温暖场所并礼貌接待体现 gracious s1。'],['The gracious host mocked the visitors, refused them water, and ordered them to stand outside in the cold.','The hostile host mocked the visitors and refused them water.','嘲弄且拒绝基本照顾是 hostile，不是亲切待客。'],[[1,'A gracious host is?',['kind and polite to guests','deliberately insulting','unwilling to acknowledge anyone'],0,'gracious s1 表示亲切有礼。'],[2,'A ruler is gracious to a defeated rival when the ruler?',['shows mercy and treats the rival generously','takes revenge without hearing any appeal','refuses all humane treatment'],0,'gracious s2 指有权者宽厚仁慈。'],[1,'Which reply is gracious?',['“Thank you for coming; please make yourself comfortable.”','“Leave immediately; you are not welcome.”','“I will not listen to you.”'],0,'礼貌欢迎来客体现 gracious。'],[2,'The director’s gracious decision was to?',['give the junior colleague a fair second chance','humiliate the colleague for a minor error','withhold earned pay as punishment'],0,'上位者给予公平机会显示宽厚。']]);
P('gradation','源自拉丁语 gradatio“逐步上升”，由 gradus“步、级”派生，指逐级变化或排列出的等级。',[1,'色彩设计','The artist used a gradation from pale yellow to deep orange, blending each shade so no sharp boundary divided the sunset.','画家把浅黄逐渐过渡到深橙，并融合各个色调，使夕阳色彩之间没有明显断界。','The artist used a gradation from pale yellow to deep orange, / blending each shade / so no sharp boundary divided the sunset.','可数或不可数名词；可指渐变过程，也可指按程度排列的等级。','颜色逐步由浅变深、无明显断点，体现 gradation。'],['The chart showed no gradation because it jumped abruptly from pale yellow to black with no intermediate steps.','The chart showed an abrupt change because it jumped directly from pale yellow to black.','没有中间层次的突变不是 gradation。'],[[1,'A gradation of colour shows?',['a gradual transition through intermediate shades','one sudden change with no middle tones','a list of unrelated words'],0,'gradation 指逐级、渐进的变化。'],[1,'Which is a gradation in rank?',['levels arranged from junior to senior','a random collection with no order','a single unranked object'],0,'等级按次序排列体现 gradation。'],[1,'A smooth gradation from blue to green would have?',['intermediate shades between the colours','only blue and green with a hard line','no visible colour'],0,'渐变包含中间色调。'],[1,'Choose the natural phrase.',['a gradation of intensity','gradation at to the river','a gradation yesterday walked'],0,'gradation of intensity 表示强度等级。']]);
P('grade','源自拉丁语 gradus“步、级”，经法语进入英语；可指质量等级、学校成绩或年级，也可作动词评分和分级。',[2,'学校评估','The teacher gave each student a grade for the research project and wrote a short comment explaining how the evidence supported the conclusion.','老师给每位学生的研究项目打了分，并写下简评，说明证据如何支持结论。','The teacher gave each student a grade for the research project / and wrote a short comment / explaining how the evidence supported the conclusion.','s1 指等级或质量级别；s2 学业分数；s3 年级；s4 作动词表示评分或分级。','老师评定项目分数，属于 grade s2。'],['The teacher graded the project by giving students a quality level, but the sentence claimed that no evaluation took place.','The teacher evaluated the project by assigning each student a grade.','assigning分数就是进行了评分；不能说没有评估。'],[[2,'A student’s grade on an essay is?',['a mark showing how the work performed','the student’s classroom year','a type of road slope'],0,'grade s2 指学业成绩。'],[3,'A child in the fifth grade is in?',['a school year or class level','the fifth quality category of a product','a slope measured in degrees'],0,'grade s3 指学校年级。'],[4,'To grade a set of apples is to?',['sort them by quality','write an essay about them','change their colour'],0,'grade s4 作动词表示按质量分类。'],[1,'A high-grade steel is steel of?',['a specified quality level','a student’s class year','a score on a test'],0,'grade s1 指品质或等级。']]);
P('gradient','源自拉丁语 gradiens“行进、上升”，经数学与地理术语发展为坡度或变化率。',[1,'地形测绘','The path has a gentle gradient, so wheelchair users can reach the lookout without climbing a steep incline.','这条路坡度平缓，轮椅使用者无需爬陡坡就能到达观景台。','The path has a gentle gradient, / so wheelchair users can reach the lookout / without climbing a steep incline.','可数名词；描述斜坡陡缓，也可在数学中表示某量的变化率。','坡道平缓与 steep incline 相对，说明 gradient 不陡。'],['The path had a steep gradient because it remained perfectly flat from end to end.','The path had a zero gradient because it remained perfectly flat from end to end.','完全平坦的路没有陡坡；其 gradient 为零或很小。'],[[1,'A road with a steep gradient?',['rises or falls sharply','is perfectly level','is made of soft fabric'],0,'gradient 表示坡度，steep 指很陡。'],[1,'Why does a gentle gradient help wheelchair access?',['the slope is not steep','the path is longer in colour','the road has no surface'],0,'坡度平缓更容易通行。'],[1,'In mathematics, a gradient can describe?',['how rapidly a quantity changes','the spelling of a word','the weight of a chair'],0,'gradient 也可表示变化率。'],[1,'Choose the natural phrase.',['a gradient of 1 in 12','a gradient at to the hill','the gradient walked quietly'],0,'gradient of 1 in 12 是描述坡度的常用形式。']]);
P('gradual','源自拉丁语 gradus“步、级”，经拉丁语 gradualis 及法语进入英语；可表示变化缓慢，也可指坡度平缓。',[1,'治疗恢复','The physiotherapist recommended a gradual return to running, increasing the distance each week rather than resuming the full route immediately.','物理治疗师建议逐渐恢复跑步，每周增加距离，而不是立刻跑回全部路程。','The physiotherapist recommended a gradual return to running, / increasing the distance each week / rather than resuming the full route immediately.','s1 指历时缓慢的过程；s2 指地形缓坡、不陡。','按周逐步增加距离说明恢复是 gradual s1。'],['The gradual recovery happened instantly in one second with no stages or change over time.','The sudden recovery happened instantly in one second with no stages or change over time.','瞬间发生而无阶段变化属于 sudden，不是 gradual。'],[[1,'A gradual change happens?',['slowly over a period of time','all at once with no transition','only in the past'],0,'gradual s1 表示逐渐发生。'],[2,'A gradual hillside is?',['sloping gently rather than steeply','vertical and impossible to climb','completely underwater'],0,'gradual s2 指坡度平缓。'],[1,'Which plan is gradual?',['increase the daily dose in small steps over several weeks','double the dose instantly without review','stop treatment before it begins'],0,'分阶段增加是逐步变化。'],[2,'The road rises gradually means it?',['goes uphill on a gentle slope','climbs a vertical wall','stays perfectly flat throughout'],0,'此处描述缓坡。']]);
P('gradually','由 gradual 加副词后缀 -ly 构成，表示随时间缓慢变化，或一步步完成某过程。',[2,'技能培训','The trainees gradually learned to operate the equipment by completing one supervised task at a time until they could manage a full shift.','学员通过一次完成一项有监督的任务逐步学会操作设备，直到能够独立负责完整班次。','The trainees gradually learned to operate the equipment / by completing one supervised task at a time / until they could manage a full shift.','s1 表示随时间慢慢发生；s2 强调按步骤逐步达到结果。','一次练习一个受监督的任务，体现 s2 的逐步学习。'],['The trainees learned gradually by mastering every advanced task in a single moment before receiving any instruction.','The trainees learned instantly by mastering the advanced tasks in a single moment.','没有教学却瞬间掌握不是 gradually learning。'],[[1,'The temperature fell gradually when it?',['decreased slowly over several hours','dropped all at once','remained exactly fixed'],0,'gradually s1 指随时间慢慢变化。'],[2,'She gradually assembled the shelf by?',['following the steps one by one','skipping every instruction and finishing before opening the box','waiting without doing any step'],0,'按步骤完成体现 gradually s2。'],[1,'Which sentence uses gradually to describe change over time?',['The fog gradually cleared by noon.','The fog vanished at once.','The fog was not present yesterday.'],0,'雾随时间慢慢散去。'],[2,'The student gradually mastered the method means?',['mastery developed step by step','the student knew it before learning','the method was never practised'],0,'gradually 表示逐步取得掌握。']]);
P('graduate','源自拉丁语 gradus“等级、步”，经中古拉丁语 graduare 与英语 graduate 发展而来；可表示毕业、毕业生、授予学位或研究生阶段。',[1,'高校毕业','After completing the required clinical placements and final examinations, Omar will graduate from the nursing programme in June.','完成规定的临床实习和期末考试后，奥马尔将于六月从护理专业毕业。','After completing the required clinical placements and final examinations, / Omar will graduate from the nursing programme / in June.','s1 动词不及物“毕业”；s2 名词“毕业生”；s3 及物“授予学位”；s4 定语“研究生的”。','奥马尔完成课程并取得毕业资格，体现 graduate s1。'],['The university graduate the student automatically by enrolling her in the first-year course.','The university graduated the student after she completed the degree requirements.','入学新生课程不是授予学位；完成学位要求后才能毕业。'],[[1,'To graduate from a course is to?',['complete it successfully','apply for it before studying','teach it without enrolling'],0,'graduate s1 指完成学业并毕业。'],[2,'A graduate is?',['a person who has completed a degree','a student who has not yet enrolled','a classroom building'],0,'graduate s2 指毕业生。'],[3,'The university graduated the candidate means the university?',['officially awarded the degree','expelled the candidate','gave a school grade only'],0,'graduate s3 作及物动词指准予毕业、授予学位。'],[4,'Graduate study usually takes place?',['after a first degree','before primary school','during a single exam'],0,'graduate s4 指本科之后的研究生阶段。']]);
P('graduation','由 graduate 加 -ion 构成，可指完成学业及毕业典礼，也指测量工具上表示刻度的分度线。',[1,'毕业典礼','Her family travelled to attend her graduation, where the dean presented certificates after the final procession across the stage.','她的家人赶来参加毕业典礼；毕业生走过舞台后，院长颁发了证书。','Her family travelled to attend her graduation, / where the dean presented certificates / after the final procession across the stage.','s1 指学业完成或纪念该事件的典礼；s2 指刻度线或分度。','家人参加颁证典礼，体现 graduation s1。'],['The thermometer’s graduation was a family ceremony with students crossing a stage and receiving diplomas.','The thermometer’s graduation marks showed the temperature scale.','温度计上的 graduation 指刻度分度，不是毕业典礼。'],[[1,'A graduation ceremony marks?',['the completion of a course of study','the beginning of primary school only','a change in weather'],0,'graduation s1 可指毕业及毕业典礼。'],[2,'The graduation on a measuring cylinder is?',['a mark showing a step on its scale','a student’s diploma','the cylinder’s handle'],0,'graduation s2 指测量仪器上的分度线。'],[1,'Families attend graduation to?',['celebrate a student completing a course','measure the classroom’s height','apply for a loan'],0,'毕业典礼庆祝学业完成。'],[2,'Graduations on a ruler help users?',['read measured intervals','identify the ruler’s owner','graduate from school'],0,'尺上的分度线用于读取长度。']]);
P('graft','植物嫁接义源自古法语 graffe“嫁接用的枝条”；政治语境中 graft 另指借职权非法谋利。',[1,'公共治理','The audit uncovered graft when officials awarded contracts to relatives in exchange for secret payments from the construction firms.','审计发现官员收取建筑公司秘密付款并把合同授予亲属，构成腐败。','The audit uncovered graft / when officials awarded contracts to relatives / in exchange for secret payments from the construction firms.','源词条将嫁接与贿赂义合并；s1 可指植物嫁接或政治腐败，依语境判别。','秘密收钱换取合同是非法谋利的 graft。'],['The gardener called the illegal cash payments for public contracts a harmless grafting technique used to join two branches.','The gardener used grafting to join a branch to a rootstock, while investigators called the secret contract payments graft.','植物嫁接与政治贿赂是不同语境；秘密付款不是园艺技术。'],[[1,'In horticulture, graft is?',['joining a plant shoot to another plant for growth','a payment made secretly to a public official','a note beneath a page'],0,'graft 的园艺义是嫁接。'],[1,'Political graft involves?',['corrupt use of office for illegal gain','growing a healthy root system','a public grant awarded fairly'],0,'graft 可指贪污受贿。'],[1,'Which sentence uses graft as a verb?',['The gardener grafted a pear branch onto the rootstock.','The officer grafted a bribe into a report.','The tree grafted a court contract.'],0,'园艺动词 graft 表示把枝条嫁接到砧木上。'],[1,'A contractor secretly pays an official to win a public job; this is?',['graft','gratitude','gradation'],0,'以秘密付款换取职务便利属于腐败。']]);
P('graham','在美式英语中指使用未筛除麸皮的全麦粉制成的；名称与美国改革者 Sylvester Graham 有关。',[1,'烘焙','The recipe calls for graham flour, which gives the crackers a nutty flavour because the wheat’s bran has not been sifted out.','配方使用全麦粉，使饼干带有坚果香，因为小麦麸皮没有被筛除。','The recipe calls for graham flour, / which gives the crackers a nutty flavour / because the wheat’s bran has not been sifted out.','美式用法，常见 graham flour/crackers；以保留麸皮的全麦粉为特征。','未筛除麸皮的面粉带来较浓谷物味，符合 graham。'],['The baker used graham flour after removing every part of the wheat bran and germ to make a refined white flour.','The baker used refined white flour after removing the bran and germ.','筛除麸皮和胚芽得到精白粉，不符合 graham flour 的全麦特征。'],[[1,'Graham flour is made from?',['whole wheat with the bran left in','only sifted wheat starch','ground rice mixed with salt'],0,'graham flour 保留小麦麸皮，是全麦粉。'],[1,'A graham cracker is associated with?',['American-style whole-wheat flour','a thin layer of snow','a musical volume marking'],0,'graham cracker 通常由 graham 全麦粉制成。'],[1,'What gives graham products a grainier flavour?',['the unsifted bran remains in the flour','all wheat material is removed','the dough contains no grain'],0,'保留麸皮可增加粗粒质感和谷物风味。'],[1,'Choose the natural phrase.',['graham crackers','graham of the river','graham very slowly'],0,'graham 可作形容词修饰 crackers。']]);
P('grain','源自古法语 grain，最终与拉丁语 granum“谷粒”相关，可指谷物、微小颗粒、少量或木石纹理。',[4,'木工','The cabinetmaker aligned the cut with the oak’s grain so the repair would follow the natural pattern of the wood rather than split across it.','木匠顺着橡木纹理下刀，使修补顺应木材的天然纹路，而不是横向劈裂。','The cabinetmaker aligned the cut with the oak’s grain / so the repair would follow the natural pattern / of the wood rather than split across it.','s1 谷物；s2 颗粒；s3 一丝、少量；s4 木材或石材的天然纹理。','沿木材天然纹路切割，体现 grain s4。'],['The cabinetmaker followed the wood’s grain by cutting across every natural line and splitting the board against its pattern.','The cabinetmaker cut against the wood’s grain by crossing its natural lines.','横切并逆着天然纹路不是顺着 grain。'],[[1,'Wheat, rice, and barley are?',['grains','footnotes','gradients'],0,'grain s1 指谷物。'],[2,'A grain of sand is?',['a very small particle','a whole field of wheat','a measurement of sound'],0,'grain s2 指细小颗粒。'],[3,'“There was not a grain of truth in the rumour” means?',['not even a tiny amount was true','the rumour was completely verified','the rumour described a crop'],0,'grain s3 可表示极少量。'],[4,'The grain of wood is its?',['natural pattern of fibres','weight in kilograms','school grade'],0,'木纹是 wood grain。']]);
P('grainy','由 grain 加 -y 构成，表示有颗粒或斑点质感，常用于照片、影像或材料表面。',[1,'影像修复','The old security recording looked grainy in low light, so the technician enhanced the image while preserving the original file for comparison.','旧监控录像在弱光下显得颗粒粗糙，技术人员增强图像时保留了原文件供比较。','The old security recording looked grainy in low light, / so the technician enhanced the image / while preserving the original file for comparison.','形容词；可指颗粒状触感或影像中明显的粗粒噪点。','弱光录像中可见粗糙颗粒，体现 grainy 的影像义。'],['The grainy photograph was perfectly smooth and sharp, with no visible dots, noise, or texture.','The crisp photograph was perfectly smooth and sharp, with no visible dots or noise.','清晰平滑、没有噪点的照片不显 grainy。'],[[1,'A grainy video often has?',['visible rough dots or image noise','perfectly smooth high detail','no picture at all'],0,'grainy 常形容画面有明显颗粒噪点。'],[1,'Which surface feels grainy?',['one with many tiny rough particles','a polished sheet of glass','a pool of still water'],0,'微小粗粒使表面呈 grainy 质感。'],[1,'Why might a low-light image look grainy?',['the recording shows visible noise','the camera captured no light or data whatsoever','the subject is made of grain'],0,'弱光下影像噪点常更明显。'],[1,'Choose the natural phrase.',['a grainy recording','grainy to arrive','a grainy of wheat'],0,'grainy 可修饰 recording。']]);
P('gram','源自希腊语 grámma“细小重量、书写单位”，经法语进入公制；等于千分之一千克。',[1,'实验室称量','The pharmacist weighed 250 grams of the compound on a calibrated balance before preparing the solution.','药剂师用校准过的天平称取250克化合物，再配制溶液。','The pharmacist weighed 250 grams of the compound / on a calibrated balance / before preparing the solution.','可数质量单位；符号 g；1 gram = 0.001 kilogram。','250克是质量单位的具体用法。'],['The package contained 250 grams, which is equal to 250 kilograms under the metric system.','The package contained 250 grams, which is equal to one quarter of a kilogram.','一千克等于1000克，因此250克是四分之一千克。'],[[1,'One gram is equal to?',['one-thousandth of a kilogram','one hundred kilograms','one kilometre'],0,'1 gram = 0.001 kilogram。'],[1,'A recipe needs 300 grams of flour. The measure refers to?',['mass','temperature','distance'],0,'gram 是质量单位。'],[1,'Which abbreviation commonly represents gram?',['g','km','L'],0,'g 是 gram 的单位符号。'],[1,'A 2-kilogram bag contains how many grams?',['2,000 grams','200 grams','20 grams'],0,'每千克1000克，2千克为2000克。']]);
P('grama','由西班牙语 grama“草”进入英语，指格兰马属多种草类，常见于干燥平原并可作牲畜饲料。',[1,'草原生态','Blue grama covered the dry prairie, providing forage for grazing animals and anchoring the soil during windy months.','干燥草原上长着蓝格兰马草，为放牧动物提供饲料，并在多风季节固定土壤。','Blue grama covered the dry prairie, / providing forage for grazing animals / and anchoring the soil during windy months.','不可数或集合名词；常见 blue grama，属于 Bouteloua 属草类。','这种草生长于干旱平原并能供牲畜采食。'],['The botanist identified the blue grama as a deep-water coral that grows only on the ocean floor.','The botanist identified the blue grama as a prairie grass adapted to dry conditions.','grama 是草类，不是海底珊瑚。'],[[1,'Grama is?',['a group of prairie grasses','a type of ocean coral','a metric unit of weight'],0,'grama 指格兰马属草类。'],[1,'Blue grama is useful on dry plains because it can?',['provide forage and help hold soil','grow only under deep seawater','measure rainfall in grams'],0,'格兰马草可作饲料并帮助固定土壤。'],[1,'Which habitat suits grama grasses?',['dry grassland','a deep ocean trench','a frozen cave with no plants'],0,'格兰马草常见于干燥平原。'],[1,'Choose the correct category.',['a grass in the genus Bouteloua','a flowering shrub in a coral reef','a school grammar rule'],0,'格兰马草属于 Bouteloua 属。']]);
P('grammar','源自希腊语 grammatikē“读写艺术”，经拉丁语与法语进入英语；指语言规则、语法书或个人的语法运用。',[1,'语言教学','The teacher compared the grammar of the two languages, showing how each one marks tense and forms questions.','老师比较了两种语言的语法，说明它们如何标记时态并构成疑问句。','The teacher compared the grammar of the two languages, / showing how each one marks tense / and forms questions.','s1 指语言结构规则；s2 指讲解规则的语法书；s3 指某人的实际语法运用。','比较时态与疑问句规则，体现 grammar s1。'],['The teacher called a dictionary a grammar because it listed word meanings but explained no rules for forming sentences.','The teacher called the reference book a dictionary because it listed word meanings.','只列词义的参考书是词典，不是讲解句法规则的 grammar。'],[[1,'The grammar of a language describes?',['rules for forming words and sentences','the number of speakers only','the colour of printed pages'],0,'grammar s1 指语言结构规则。'],[2,'A grammar is a book that?',['explains the rules of a language','lists only weather forecasts','contains no language examples'],0,'grammar s2 可指语法书。'],[3,'A learner’s grammar may be judged by?',['how the learner actually uses grammatical rules','the learner’s shoe size','the paper quality of a textbook'],0,'grammar s3 指个人实际语法使用。'],[1,'Which topic belongs to grammar?',['how word order forms a question','how a bridge is painted','how much a package weighs'],0,'疑问句语序属于语法规则。']]);
P('grammatical','由 grammar 加形容词后缀 -ical 构成，可指与语言规则有关，也可指符合某种语言规则。',[2,'编辑校对','The editor changed “She walk home” to “She walks home,” making the sentence grammatical in the present tense.','编辑把“She walk home”改为“She walks home”，使句子符合一般现在时的语法规则。','The editor changed “She walk home” to “She walks home,” / making the sentence grammatical / in the present tense.','s1 指语法方面的；s2 指句子或形式符合语法规则。','主语 she 要求动词加 -s，修改后句子符合语法。'],['The sentence “She walk home every day” was grammatical because the singular subject correctly takes a bare verb in the present tense.','The sentence “She walks home every day” was grammatical because the singular subject takes a third-person singular verb.','一般现在时单数主语 she 后应为 walks，而不是 walk。'],[[2,'A grammatical sentence is one that?',['follows the rules of its language','contains only nouns','has been translated into every language'],0,'grammatical s2 表示合乎语法。'],[1,'A grammatical analysis studies?',['how words and sentence rules work','the weight of a book','the shape of a mountain'],0,'s1 指语法方面的研究。'],[2,'Which is grammatical in standard English?',['They are ready.','They is ready.','They am ready.'],0,'复数主语 they 与 are 搭配。'],[1,'A grammatical category may include?',['tense or number','a building’s address','the temperature of a room'],0,'时态和数是语法范畴。']]);
P('grammatical person','由 grammatical 与 person 组成，指语法中的第一、第二或第三人称类别。',[1,'语言学','In the sentence “I told you that she was ready,” the pronouns mark first, second, and third grammatical person.','在“I told you that she was ready”这句话中，代词分别标示第一、第二和第三人称。','In the sentence “I told you that she was ready,” / the pronouns mark first, second, / and third grammatical person.','不可数术语；first person 指说话者，second person 指听者，third person 指谈论的人或物。','I、you、she 分别对应第一、第二、第三人称。'],['The pronoun “I” is third grammatical person because it refers to the person speaking.','The pronoun “I” is first grammatical person because it refers to the speaker.','说话者自身使用第一人称 I。'],[[1,'“We” is which grammatical person?',['first person','second person','third person'],0,'we 指说话者一方，是第一人称复数。'],[1,'In “You can begin,” you is?',['second grammatical person','first grammatical person','third grammatical person'],0,'you 指对话听者，是第二人称。'],[1,'In “They arrived,” they is?',['third grammatical person','second grammatical person','first grammatical person'],0,'they 指说话者和听者之外的人，是第三人称。'],[1,'Grammatical person classifies pronouns by?',['their relation to the speaker and listener','their printed font size','their position in a dictionary'],0,'人称依代词与说话者和听者的关系区分。']]);
P('gramme','源自法语 gramme，来自希腊语 grámma；英式拼写 gramme 与 gram 同义，均为公制质量单位。',[1,'烹饪','The baker weighed 500 grammes of flour on the kitchen scale before adding the yeast and warm water.','面包师先用厨房秤称取500克面粉，再加入酵母和温水。','The baker weighed 500 grammes of flour / on the kitchen scale / before adding the yeast and warm water.','名词，英式拼写常见 gramme；1000 grammes = 1 kilogram。','500 grammes 是质量单位的数量用法。'],['The parcel weighed 500 grammes, which is equal to half a kilogram because one kilogram contains ten grammes.','The parcel weighed 500 grammes, which is equal to half a kilogram because one kilogram contains 1,000 grammes.','一千克等于1000克，不是10克。'],[[1,'One kilogram contains?',['1,000 grammes','100 grammes','10 grammes'],0,'公制中1 kg = 1000 g。'],[1,'Gramme and gram are?',['two spellings of the same metric mass unit','units for measuring distance','two different kinds of temperature'],0,'gramme 是 gram 的拼写变体。'],[1,'A recipe asks for 250 grammes of sugar. This measures?',['mass','volume in litres','time'],0,'gramme 是质量单位。'],[1,'Which abbreviation may represent a gramme?',['g','km','°C'],0,'gramme 常用符号 g。']]);
P('granary','源自拉丁语 granarium“粮食储藏处”，与 granum“谷粒”相关；可指储粮建筑，也可比喻高产粮区。',[1,'农业储存','After the harvest, workers moved the dry wheat into the granary, where ventilation kept moisture from spoiling the grain.','收割后，工人把干燥小麦运进粮仓，通风系统防止谷物受潮变质。','After the harvest, workers moved the dry wheat into the granary, / where ventilation kept moisture / from spoiling the grain.','s1 指储粮建筑；s2 比喻高产粮的地区。','建筑内储存小麦，体现 granary s1。'],['The farm stored its grain in the granary by scattering it outdoors where rain could soak and spoil it.','The farm stored its grain in a granary with a dry, ventilated interior.','露天淋雨会损坏粮食，不是适宜的储粮方式。'],[[1,'A granary is a building used to?',['store grain','repair ships','teach grammar'],0,'granary s1 指粮仓。'],[2,'A region called “the granary of the country” is?',['a major grain-producing area','a place where no crops grow','a warehouse for books only'],0,'granary s2 比喻粮食产区。'],[1,'Why keep grain in a dry granary?',['to prevent moisture and spoilage','to make it grow in storage','to turn it into stone'],0,'干燥储存可避免粮食受潮变质。'],[2,'A country’s granary supplies?',['a large share of its grain','only its mineral fuel','its school report cards'],0,'比喻用法指为国家提供大量粮食的地区。']]);
P('grand','源自古法语 grand，最终来自拉丁语 grandis“大的、重要的”；可形容宏伟、重大、傲慢，也作俚语指一千英镑或美元。',[1,'建筑','The museum’s grand staircase curves beneath a glass dome, giving the entrance hall an impressive sense of scale.','博物馆宏伟的楼梯在玻璃穹顶下盘旋，使入口大厅显得气势壮观。','The museum’s grand staircase curves beneath a glass dome, / giving the entrance hall / an impressive sense of scale.','s1 宏伟；s2 重大或最终；s3 傲慢；s4 俚语“一千”。需由上下文判义。','楼梯与穹顶带来壮观尺度，体现 grand s1。'],['The grand staircase was a tiny temporary step stool hidden beneath the ordinary doorway.','The modest step stool was a tiny temporary platform beneath the doorway.','微小临时脚凳不具有 grand 的宏伟壮丽。'],[[1,'A grand building is?',['large and impressive','tiny and plain','made only of paper'],0,'grand s1 指宏伟壮观。'],[2,'The grand total on a bill is?',['the final overall amount','the first item only','a thousand dollars in every case'],0,'grand s2 可指最终总计。'],[3,'A grand manner may suggest someone is?',['acting superior or arrogant','being modest and deferential','feeling grateful'],0,'grand s3 可指傲慢自大。'],[4,'In informal money talk, “two grand” often means?',['two thousand pounds or dollars','two pounds or dollars','two hundred thousand'],0,'grand s4 俚语指一千英镑或美元。']]);
P('grandchild','由 grand 与 child 组成，指某人儿子或女儿的孩子，不区分孙子、孙女或外孙。',[1,'家庭关系','Mina’s grandchild visits every Sunday, bringing drawings from school to show the grandparents.','米娜的孙辈每周日来访，带来学校画作给祖父母看。','Mina’s grandchild visits every Sunday, / bringing drawings from school / to show the grandparents.','可数名词；性别不限定，复数为 grandchildren。','来访的孩子是祖父母的子女所生，关系为 grandchild。'],['Mina called her grandmother’s mother her grandchild, although that person belongs to an earlier generation.','Mina called her grandmother’s mother her great-grandmother, since she belongs to an earlier generation.','祖母的母亲是曾祖母，不是其后代 grandchild。'],[[1,'A grandchild is?',['the child of someone’s son or daughter','the parent of someone’s mother','a sibling of someone’s child'],0,'grandchild 指子女所生的孩子。'],[1,'If your son has a daughter, she is your?',['granddaughter','grandmother','grandparent'],0,'儿子的女儿是孙女。'],[1,'The plural of grandchild is?',['grandchildren','grandchilds','grandchildes'],0,'grandchild 的复数是 grandchildren。'],[1,'A grandchild belongs to which generation?',['one below their grandparent’s children','one above their great-grandparents','the same generation as their parent'],0,'孙辈比其父母低一代。']]);
P('granddaughter','由 grand 与 daughter 组成，指自己儿子或女儿的女儿。',[1,'家庭聚会','At the reunion, Leon introduced his granddaughter, who had just started school and was eager to meet her cousins.','家庭团聚时，利昂介绍了刚入学、迫不及待想见表亲的孙女。','At the reunion, Leon introduced his granddaughter, / who had just started school / and was eager to meet her cousins.','可数亲属名词；不论经儿子还是女儿而来，都可称 granddaughter。','她是利昂子女的女儿，关系为 granddaughter。'],['Leon called the daughter of his child his grandson.','Leon called the daughter of his child his granddaughter.','子女的女儿是 granddaughter；grandmother 是母亲一代的女性长辈。'],[[1,'A granddaughter is?',['the daughter of one’s child','the mother of one’s parent','the sister of one’s spouse'],0,'granddaughter 指子女的女儿。'],[1,'Your daughter’s daughter is your?',['granddaughter','grandmother','aunt'],0,'女儿的女儿是外孙女。'],[1,'Granddaughter differs from grandson by?',['the child’s gender','the child’s age','the parent’s country'],0,'granddaughter 指女性孙辈。'],[1,'Choose the natural sentence.',['His granddaughter brought him a drawing.','His granddaughter is the mother of his father.','He married his granddaughter at the reunion.'],0,'granddaughter 是其子女的女儿。']]);
P('grande','借自西班牙语或意大利语 grande“大、盛大”，可用于专名或描述规模，也用于某些咖啡店的中杯规格。',[2,'咖啡点单','I ordered a grande iced coffee, the shop’s medium-large size, and asked for oat milk instead of dairy.','我点了一杯大杯冰咖啡（该店的中大规格），并要求用燕麦奶代替乳制品。','I ordered a grande iced coffee, / the shop’s medium-large size, / and asked for oat milk instead of dairy.','s1 在外来语名称中表示大或盛大；s2 是部分连锁咖啡店使用的中杯规格名。','点单语境中 grande 是该店的饮品规格名称 s2。'],['The customer ordered a grande in that café, where grande is the smallest size and holds less than a short.','The customer ordered a short in that café, where short is the smallest size.','在该店 grande 不是最小规格；此处应改为 short。'],[[2,'At a coffee chain using these labels, a grande is?',['a named drink size, often medium-large','a kind of pastry','a payment deadline'],0,'grande s2 是部分咖啡店的杯型规格。'],[1,'In a Spanish name, grande can indicate something?',['large or impressive','very small','made of grain'],0,'借词 grande 可表示大或盛大。'],[2,'If a menu lists tall, grande, and venti, grande is?',['one of the chain’s drink sizes','a type of coffee bean only','a cup made of glass'],0,'这些标签用于区分饮品规格。'],[1,'The phrase “Grande Ballroom” uses grande to suggest what?',['a large or impressive entrance','a tiny hidden entrance','a grammatically incorrect sentence'],0,'grande 的借词义表示大或壮观。']]);
P('grandeur','源自法语 grandeur“宏大、壮丽”，grand 来自拉丁语 grandis“大的、壮观的”。',[1,'古迹保护','Despite years of damage, the cathedral retained its grandeur through soaring arches and carefully restored stone carvings.','尽管多年受损，大教堂仍凭借高耸的拱门和精心修复的石雕保有壮丽气势。','Despite years of damage, the cathedral retained its grandeur / through soaring arches / and carefully restored stone carvings.','不可数名词；描述宏伟的规模与美感，常用于建筑、景观或典礼。','拱门和石雕使大教堂保持壮丽感。'],['The cathedral’s grandeur came from its tiny scale, plain walls, and complete absence of impressive features.','The cathedral’s simplicity came from its tiny scale, plain walls, and lack of ornate features.','朴素微小、毫无壮观特征体现 simplicity，不是 grandeur。'],[[1,'Grandeur is?',['great beauty and impressive size','a small amount of food','a school mark'],0,'grandeur 指壮丽、宏伟。'],[1,'Which view has grandeur?',['a vast canyon framed by towering cliffs','a plain empty box','a tiny stain on a desk'],0,'辽阔峡谷和高耸峭壁带来壮丽感。'],[1,'A building’s grandeur may come from?',['its scale and impressive design','its lack of any structure','its low price only'],0,'建筑的规模和设计可形成 grandeur。'],[1,'Choose the natural phrase.',['the grandeur of the palace','grandeur to carry a small cup','grandeur at the grammar'],0,'the grandeur of + 建筑或景观是自然搭配。']]);
P('grandfather','由 grand 与 father 组成，指父亲或母亲的父亲。',[1,'家庭回忆','Her grandfather taught her to repair bicycles in the garage, and she still uses his old tools for small fixes.','她的祖父在车库里教她修自行车；如今她还用着他的旧工具做小修理。','Her grandfather taught her to repair bicycles / in the garage, / and she still uses his old tools for small fixes.','可数亲属名词；包括父系祖父和母系外祖父，口语也常用 grandpa。','教她修车的长辈是其父母一方的父亲。'],['Her grandfather was the mother of her father, who had taught her to repair bicycles.','Her grandmother was the mother of her father, who had taught her to repair bicycles.','父亲的母亲是 grandmother；grandfather 指父亲或母亲的父亲。'],[[1,'Your mother’s father is your?',['grandfather','granddaughter','grandchild'],0,'母亲的父亲是外祖父。'],[1,'A grandfather is?',['the father of one of your parents','the son of your child','your parent’s sister'],0,'grandfather 指父母的父亲。'],[1,'Which person is someone’s grandfather?',['the father of that person’s mother','the daughter of that person’s son','the mother of that person’s father'],0,'母亲的父亲属于 grandfather。'],[1,'Grandpa is a common informal word for?',['grandfather','granddaughter','grandchild'],0,'grandpa 是 grandfather 的口语称呼。']]);
P('grandiose','由 grand 加 -iose 构成，表示看起来宏大壮观；常带贬义，指计划或表达过于夸张、野心过大。',[1,'项目评审','The startup’s grandiose plan promised to build a city on Mars within two years, despite having no launch vehicle or funding.','这家初创公司的计划夸张到承诺两年内在火星建城，尽管它既没有运载火箭，也没有资金。','The startup’s grandiose plan promised to build a city on Mars within two years, / despite having no launch vehicle or funding.','形容词；可指宏大壮观，也常暗含不切实际、炫耀或野心过度。','资源不足却承诺两年内在火星建城，显得不切实际而 grandiose。'],['The modest plan was grandiose because it proposed only a small repair that the team could complete tomorrow.','The ambitious plan was modest because it proposed only a small repair that the team could complete tomorrow.','小规模且可轻松完成的维修不显夸张宏大。'],[[1,'A grandiose promise may be?',['showy and far too ambitious','carefully limited and realistic','a statement of a simple fact'],0,'grandiose 常批评夸张不切实际。'],[1,'Which proposal sounds grandiose?',['build a palace on the moon next month with no budget','replace one broken chair this afternoon','write a short report by Friday'],0,'无资源却承诺短期月球建宫属于宏大空想。'],[1,'Does grandiose always praise a plan?',['No; it often suggests excessive ambition or show.','Yes; it always means practical.','No; it means completely invisible.'],0,'grandiose 常含负面评价。'],[1,'Choose the natural phrase.',['a grandiose scheme','grandiose at the spoon','a grandiose measured in grams'],0,'grandiose 可修饰 scheme。']]);
P('grandma','grandmother 的口语缩略形式，指父亲或母亲的母亲。',[1,'家庭聚餐','The children called their grandma every Sunday to hear stories about the neighbourhood where she grew up.','孩子们每周日给奶奶打电话，听她讲成长街区的故事。','The children called their grandma every Sunday / to hear stories / about the neighbourhood where she grew up.','非正式亲属称呼；具体指祖母或外祖母，取决于家族关系。','孩子们给上一代母亲长辈打电话，称 grandma。'],['The children called their grandma their grandson because she was the mother of one of their parents.','The children called their grandma their grandmother because she was the mother of one of their parents.','grandson 是孙子或外孙，女性长辈应称 grandma/grandmother。'],[[1,'Grandma is an informal term for?',['a grandmother','a grandson','a granddaughter'],0,'grandma 是 grandmother 的口语形式。'],[1,'Your father’s mother may be called your?',['grandma','grandson','grandchild'],0,'父亲的母亲是祖母。'],[1,'Which sentence uses grandma naturally?',['My grandma taught me her favourite recipe.','My grandma is the son of my child.','I called the school my grandma.'],0,'grandma 指祖母或外祖母。'],[1,'A child may use Grandma as?',['a familiar name for a grandmother','a name for a school grade','a word for a grain'],0,'Grandma 是家庭中对祖母的熟悉称呼。']]);
P('grandmother','由 grand 与 mother 组成，指父亲或母亲的母亲。',[1,'家族探访','Their grandmother lives near the coast and keeps photographs of every grandchild in a frame by the kitchen window.','他们的祖母住在海边，厨房窗边的相框里放着每个孙辈的照片。','Their grandmother lives near the coast / and keeps photographs of every grandchild / in a frame by the kitchen window.','可数亲属名词；既可指祖母，也可指外祖母。','照片中的长辈是其父母之一的母亲。'],['Their grandmother was their father’s father and lived near the coast with the family photographs.','Their grandfather was their father’s father and lived near the coast with the family photographs.','父亲的父亲是 grandfather；grandmother 指父母的母亲。'],[[1,'A grandmother is?',['the mother of one’s father or mother','the father of one’s parent','the daughter of one’s child'],0,'grandmother 指父母一方的母亲。'],[1,'Your mother’s mother is your?',['grandmother','grandson','grandfather'],0,'母亲的母亲是外祖母。'],[1,'Grandmother is the standard form; grandma is usually?',['more informal','a masculine term','a type of grain'],0,'grandma 更口语。'],[1,'Choose the natural phrase.',['visit their grandmother','visit their grandmother’s grandson as a parent','grandmother the bridge'],0,'grandmother 可作 visit 的宾语。']]);
P('grandparent','由 grand 与 parent 组成，统称自己母亲或父亲的父亲或母亲。',[1,'育儿','A grandparent collected the twins from school while their parents attended a late appointment.','父母去赴较晚的预约时，一位祖父母替双胞胎接了学。','A grandparent collected the twins from school / while their parents attended / a late appointment.','可数亲属名词；涵盖 grandfather 与 grandmother，复数 grandparent(s)。','代替父母接孩子的长辈是祖父母一方。'],['The child’s grandparent was the child’s son, who belonged to a younger generation.','The child’s grandparent was the parent of the child’s mother or father.','孩子的儿子属于下一代，是 descendant，不是 grandparent。'],[[1,'A grandparent is?',['a parent of someone’s mother or father','a child of someone’s child','a sibling of someone’s spouse'],0,'grandparent 指父母的父母。'],[1,'A grandparent may be?',['a grandmother or grandfather','only a cousin','only a grandchild'],0,'grandparent 是祖父母/外祖父母的统称。'],[1,'A child’s grandparents belong to?',['the generation above the child’s parents','the same generation as the child','the generation below the child'],0,'祖父母比父母高一代。'],[1,'Choose the natural phrase.',['spend the weekend with a grandparent','a grandparent is the child’s grandson','grandparent the kitchen'],0,'与祖父母共度周末是自然表达。']]);
P('grandson','由 grand 与 son 组成，指自己儿子或女儿的儿子。',[1,'家庭关系','Ravi’s grandson sent a postcard from university, describing his first week away from home.','拉维的孙子从大学寄来明信片，讲述离家后的第一个星期。','Ravi’s grandson sent a postcard / from university, / describing his first week away from home.','可数亲属名词；性别为男性，关系经自己的子女而来。','写信者是拉维某个子女的儿子，称 grandson。'],['The family called the son of their daughter their granddaughter.','The family called the son of their daughter their grandson.','女儿的儿子是外孙 grandson，不是祖父。'],[[1,'A grandson is?',['the son of one’s child','the father of one’s mother','the daughter of one’s child'],0,'grandson 指自己子女的儿子。'],[1,'Your son’s son is your?',['grandson','grandmother','granddaughter'],0,'儿子的儿子是孙子。'],[1,'Grandson differs from granddaughter by?',['the child’s gender','whether the parent is married','the child’s school grade'],0,'grandson 指男性孙辈。'],[1,'Choose the natural sentence.',['Their grandson visits them after class.','Their grandson is the mother of their parent.','Their grandson is a grandparent of his own father.'],0,'孙辈可探望祖父母。']]);
P('granite','经意大利语 granito“颗粒状的石头”进入英语；指坚硬的花岗岩，也可比喻坚毅持久。',[1,'建筑材料','The memorial was carved from granite because the hard grey rock withstands weathering and preserves fine lettering outdoors.','纪念碑用花岗岩雕刻，因为这种坚硬的灰色岩石耐风化，能在户外保存精细刻字。','The memorial was carved from granite / because the hard grey rock withstands weathering / and preserves fine lettering outdoors.','s1 为坚硬火成岩；s2 比喻坚毅持久的品质或决心。','耐风化的灰色石材是 granite。'],['The sculptor chose soft cotton as granite because it could be folded easily and dissolved in water.','The sculptor chose granite for the memorial because it was hard and durable.','棉布柔软且可溶，不是坚硬耐久的花岗岩。'],[[1,'Granite is?',['a very hard rock often used for buildings','a soft plant fibre','a metric weight unit'],0,'granite s1 指坚硬的花岗岩。'],[2,'A person with a will of granite has?',['a firm and enduring resolve','a preference for soft stone','a fear of making decisions'],0,'比喻义 s2 指坚定不屈。'],[1,'Why use granite for a monument?',['it can withstand weathering','it melts at room temperature','it is a liquid'],0,'花岗岩坚硬且耐久。'],[2,'“Her courage was granite” suggests she was?',['steadfast under pressure','easily discouraged','made of rock literally'],0,'granite 比喻坚毅。']]);
P('grant','源自古法语 granter“同意、授予”，词源最终与拉丁语 credere“相信、托付”相关；可授予、准许、承认，也指专款。',[4,'科研资助','The foundation awarded a research grant to the team after reviewing its proposal, budget, and plan for sharing the results.','基金会审查团队的提案、预算和成果共享计划后，向其拨付了研究经费。','The foundation awarded a research grant to the team / after reviewing its proposal, budget, / and plan for sharing the results.','s1 正式授予；s2 准许请求；s3 勉强承认；s4 指特定用途的拨款。','基金会提供特定研究资金，体现 grant s4。'],['The agency granted the application by rejecting it and refusing to allow the requested permit.','The agency denied the application by rejecting it and refusing to allow the requested permit.','拒绝申请应为 deny；grant 表示批准或授予。'],[[1,'To grant a scholarship is to?',['formally award it','take it away','hide the application'],0,'grant s1 表示正式授予。'],[2,'The court granted the request means the court?',['allowed it','rejected it','forgot it'],0,'grant s2 表示准许请求。'],[3,'“I grant that the task was difficult” means?',['I admit that it was difficult.','I forbid anyone to discuss it.','I claim the task was easy.'],0,'grant s3 可表示承认某事属实。'],[4,'A research grant is?',['money provided for a particular purpose','a school grade','a payment deadline'],0,'grant s4 指专项资金或补助。']]);
P('granular','由 granule 加 -ar 构成，源自拉丁语 granum“谷粒”；可指颗粒状，也可指数据细分到小单位。',[2,'数据分析','The dashboard gives a granular view of daily sales by product and region, allowing managers to spot small changes hidden in monthly totals.','仪表板按产品和地区展示每日销售的细分数据，使经理能发现月度总数中隐藏的小变化。','The dashboard gives a granular view of daily sales / by product and region, / allowing managers to spot small changes hidden in monthly totals.','s1 指由小颗粒构成；s2 指信息拆分为细小、详细的层级。','按产品、地区和日期拆分数据，体现 granular s2。'],['The granular report showed only one yearly total and no breakdown by product, day, or region.','The summary report showed only one yearly total and no breakdown by product, day, or region.','只有年度总数而无细分信息，不是 granular report。'],[[1,'Granular sugar consists of?',['small separate grains or crystals','one smooth sheet of glass','a liquid with no particles'],0,'granular s1 指颗粒状。'],[2,'Granular data are?',['broken into small detailed categories','combined into one vague total','deleted permanently'],0,'granular s2 指细分的数据。'],[1,'Which substance has a granular texture?',['coarse salt with visible crystals','a smooth rubber sheet','still air'],0,'可见盐晶体现颗粒质地。'],[2,'A granular budget report may list?',['spending by individual category and month','only one total with no details','the colour of the office walls'],0,'按类别和月份列明细是颗粒化数据。']]);
P('granule','源自拉丁语 granulum“细小谷粒”，是 granum“谷粒”的指小形式，指物质中的微小颗粒。',[1,'药品制造','Each granule of the powdered medicine dissolved slowly in water, so the technician stirred until the mixture became uniform.','药粉中的每个小颗粒都在水中慢慢溶解，技术员持续搅拌直到混合均匀。','Each granule of the powdered medicine dissolved slowly in water, / so the technician stirred / until the mixture became uniform.','可数名词；指很小的一粒物质，如糖、粉末或土壤颗粒。','药粉的单个微粒是 granule。'],['The granule was a vast mountain range visible from space rather than a tiny particle of matter.','The landform was a vast mountain range visible from space rather than a granule.','山脉是宏大地形，不是微小颗粒。'],[[1,'A granule is?',['a tiny grain or particle','a large building','a school course'],0,'granule 指细小颗粒。'],[1,'Which can be described as a granule?',['one tiny crystal of sugar','a whole bag of flour','a river valley'],0,'单颗糖晶体可称 granule。'],[1,'Granules of fertiliser are?',['small separate pieces','one continuous sheet','a kind of weather forecast'],0,'颗粒状肥料由许多小粒组成。'],[1,'Choose the natural phrase.',['a granule of salt','a granule of a mountain range','granule to the meeting'],0,'a granule of salt 是自然表达。']]);
P('grape','源自古法语 grape“葡萄串、葡萄”，词源与一簇或钩状物的旧词形相关；可指果实或葡萄藤。',[1,'果园','The farmer harvested each grape by hand because the fruit was ripe but the thin skins split easily in the mechanical picker.','果实已成熟，但果皮很薄、机械采摘容易压裂，因此农民逐粒手工采葡萄。','The farmer harvested each grape by hand / because the fruit was ripe / but the thin skins split easily in the mechanical picker.','s1 指葡萄果实；s2 可指结葡萄的藤本植物，依上下文区别。','工人采摘的是成熟果实。'],['The botanist called the grape the wooden support post that held the vine above the soil.','The botanist called the grapevine the plant that grew above the soil.','grape 可指果实或藤；支撑藤蔓的木柱不是葡萄。'],[[1,'A grape is?',['a small round fruit that grows in bunches','a metal fastening','a type of grain scale'],0,'grape s1 指成串生长的圆形果实。'],[2,'A gardener pruned the grape because it?',['was the vine bearing the fruit','was one berry in the harvest basket','was a measuring instrument'],0,'grape s2 可指葡萄藤。'],[1,'Which snack contains grapes?',['a bowl of fresh berries from a vine','a bag of dry wheat','a spoonful of gravy'],0,'葡萄果实可直接食用。'],[2,'Which phrase refers to the plant rather than the fruit?',['a grape trained along a trellis','a grape served in a bowl','a grape weighed on a scale'],0,'沿棚架生长的 grape 指藤蔓。']]);
P('graph','源自希腊语 graphē“书写、图画”，来自 graphein“写”；可指表示变量关系的图表，也可作动词绘制图表。',[1,'数据呈现','The graph shows monthly rainfall on the vertical axis and time on the horizontal axis, making the dry season easy to identify.','图表以纵轴表示月降雨量、横轴表示时间，使旱季一目了然。','The graph shows monthly rainfall on the vertical axis / and time on the horizontal axis, / making the dry season easy to identify.','s1 为显示数量关系的图；s2 作动词表示用图表呈现数据。','横纵坐标展示降雨量与时间的关系，是 graph s1。'],['The graph displayed no relationship between variables because it contained only an unrelated decorative photograph.','The photograph illustrated the report, while a graph would show the relationship between measured variables.','纯装饰照片不是展示数量关系的 graph。'],[[1,'A graph can show?',['how two measured quantities relate','the sound of a spoken sentence','a family tree without labels only'],0,'graph s1 以图表展示变量关系。'],[2,'To graph a set of results is to?',['represent them in a graph','erase them from a notebook','read them aloud without plotting'],0,'graph s2 是把信息绘成图表。'],[1,'Which graph feature helps compare values?',['axes and plotted data points','a decorative frame alone','the paper’s colour'],0,'坐标轴和数据点呈现变量关系。'],[1,'Choose the natural sentence.',['The graph indicates a steady increase.','The graph indicates into a table loudly.','Graph is the data were.'],0,'graph 可作主语说明趋势。']]);
P('graphic','源自希腊语 graphikos“与书写或绘画有关”，经拉丁语和法语进入英语；可指生动具体，也可指图像或图表。',[1,'急救培训','The manual gives a graphic account of the injury, describing the damage in detail so trainees understand why protective gloves matter.','手册对伤情作了生动具体的描述，让学员理解防护手套为何重要。','The manual gives a graphic account of the injury, / describing the damage in detail / so trainees understand why protective gloves matter.','形容词；s1 可指描写细致生动，有时因内容令人不适；也可指图像/图表相关。','详细描写受伤情况，体现 graphic s1。'],['The graphic description was vague and omitted every visible detail, leaving readers unable to picture the injury.','The vague description omitted visible details, leaving readers unable to picture the injury.','graphic 描写通常细节鲜明，不是含糊省略信息。'],[[1,'A graphic account is?',['vivid and detailed','short and completely vague','a mathematical unit only'],0,'graphic s1 指描写生动、细节清楚。'],[1,'A graphic warning may include?',['a clear image showing the hazard','only an unrelated sound','a blank page'],0,'graphic 可表示以图像呈现信息。'],[1,'Why might someone avoid graphic medical images?',['they show disturbing details','they contain no visual information','they are always written in verse'],0,'graphic images可能直接展示令人不适的细节。'],[1,'Choose the natural phrase.',['a graphic illustration of the process','graphic to arrive early','a graphic of the temperature only in speech'],0,'graphic 可修饰 illustration。']]);
P('graphics','由 graphic 加 -s 构成，指用于呈现信息的图像、图表或计算机绘图。',[1,'软件设计','The presentation uses simple graphics to show how water moves through the treatment system, letting visitors follow each stage at a glance.','演示文稿用简明图示展示水如何流经处理系统，让参观者一眼看清每个阶段。','The presentation uses simple graphics / to show how water moves through the treatment system, / letting visitors follow each stage at a glance.','复数形式作集合名词；可包括图片、图表、屏幕图形或计算机图像。','图示帮助解释系统流程，符合 graphics。'],['The report’s graphics were a spoken interview with no picture, diagram, or computer image.','The report’s graphics were diagrams showing the process.','纯口头访谈不是用于视觉呈现的 graphics。'],[[1,'Graphics in a report are?',['pictures or diagrams used to present information','a list of spoken comments','a type of grass seed'],0,'graphics 指信息图像或图示。'],[1,'Which task might a graphics designer perform?',['create an explanatory diagram for a website','measure a river’s depth','prepare a grave'],0,'设计网站图示属于 graphics 工作。'],[1,'A computer game’s graphics refer to?',['its visual images and rendered scenes','its players’ spoken strategy only','the cost of its batteries'],0,'游戏画面属于 computer graphics。'],[1,'Choose the natural phrase.',['graphics package','graphics to drink','a graphics of the meeting'],0,'graphics 可指图像，也常搭配 graphics package。']]);
P('graphite','由希腊语 graphein“书写”加矿物后缀 -ite 构成，因石墨可用于书写而得名；石墨是柔软的灰黑色导电碳。',[1,'材料科学','The engineer chose graphite for the electrode because its carbon structure conducts electricity while remaining lightweight.','工程师选择石墨制作电极，因为其碳结构既能导电又较轻。','The engineer chose graphite for the electrode / because its carbon structure conducts electricity / while remaining lightweight.','不可数矿物名；石墨是碳的一种晶体形态，不是金属铅。','用于电极的导电碳材料是 graphite。'],['The engineer chose graphite because it was a liquid metal that could not conduct electricity.','The engineer chose graphite because it is a soft carbon material that conducts electricity.','石墨是能导电的固态碳，不是液态金属。'],[[1,'Graphite is a form of?',['carbon','iron','liquid water'],0,'graphite 是碳的晶体形态。'],[1,'Why is graphite used in some electrodes?',['it conducts electricity','it is a gas at room temperature','it cannot carry charge'],0,'石墨可以导电。'],[1,'The dark core of a pencil is primarily?',['graphite mixed with clay','pure lead metal','charcoal mixed with salt'],0,'铅笔芯主要由石墨和黏土组成，并非铅。'],[1,'Choose the correct description.',['soft grey-black graphite','transparent liquid graphite','a bright green grasshopper'],0,'石墨通常柔软、灰黑且导电。']]);
P('graphology','由 graph “书写”与 -logy“研究”构成，指分析笔迹的学科；据此推断人格缺乏充分科学支持。',[1,'证据评估','The hiring panel did not use graphology to judge applicants, because handwriting-based personality claims have little scientific support.','招聘小组没有用笔迹学评估申请人，因为仅凭字迹推断人格缺少科学支持。','The hiring panel did not use graphology to judge applicants, / because handwriting-based personality claims / have little scientific support.','不可数名词；研究或解读笔迹，尤其试图由笔迹推断人格；这类判断可靠性有限。','小组拒绝凭字迹推断性格，准确呈现该领域及其证据局限。'],['The hiring panel relied on graphology because every handwriting sample scientifically proves an applicant’s personality with certainty.','The hiring panel avoided graphology because handwriting alone cannot reliably prove an applicant’s personality.','笔迹分析的人格结论缺少强科学支撑，不能视为确定证明。'],[[1,'Graphology is the study or analysis of?',['handwriting, sometimes used to infer personality','weather patterns in grasslands','the weight of a carbon atom'],0,'graphology 指笔迹分析。'],[1,'Why should graphology-based hiring claims be treated cautiously?',['handwriting alone has little scientific support as a personality test','every personality trait is directly visible in letters','it measures job performance perfectly'],0,'仅凭笔迹推断人格缺乏充分科学依据。'],[1,'A graphologist may examine?',['the shapes and patterns of handwriting','a graph of rainfall only','the roots of a plant'],0,'graphology 的研究对象是笔迹。'],[1,'Choose the accurate statement.',['Graphology is not a reliably established personality test.','Graphology proves character with certainty.','Graphology is a branch of astronomy.'],0,'笔迹学的性格推断并无可靠科学保证。']]);
P('grapple','其历史来源与抓钩或抓取相关词形有关，具体演变有不确定处；现代指近身扭打或努力处理困难问题。',[1,'政策研究','The research team is still grappling with how to protect private data while publishing results that other scientists can reproduce.','研究团队仍在努力解决如何保护隐私数据、同时让其他科学家复现结果的问题。','The research team is still grappling with how to protect private data / while publishing results / that other scientists can reproduce.','s1 可指近身搏斗，也可比喻艰难应对问题；常用 grapple with。','团队正在艰难处理相互冲突的要求，符合 grapple with。'],['The team grappled with the issue by ignoring it completely and making no attempt to understand or address it.','The team avoided the issue by ignoring it completely and making no attempt to understand or address it.','完全不处理问题不是 grapple with，而是回避。'],[[1,'To grapple with a difficult problem is to?',['struggle seriously to understand or solve it','pretend it does not exist','celebrate it before studying it'],0,'grapple with 表示认真努力地应对难题。'],[1,'Two wrestlers grapple when they?',['fight while holding one another closely','write letters from separate rooms','measure the ring’s width'],0,'grapple 的字面义可指近身扭打。'],[1,'Which sentence uses grapple figuratively?',['The committee grappled with the cost of expanding the service.','The wrestlers grappled on the mat.','The grasshopper crossed the field.'],0,'委员会艰难处理成本问题是比喻义。'],[1,'Choose the common construction.',['grapple with a challenge','grapple at a challenge','grapple to the challenge'],0,'常用 grapple with + 问题或挑战。']]);
P('grasp','源自古英语 graspian“抓住、攫取”，可指牢牢握住、完全理解、把握机会，也可作名词指理解力或紧握。',[2,'技术培训','The apprentice quickly grasped why the valve had to close before the pump started, then explained the sequence to the rest of the crew.','学徒很快理解了为何必须先关闭阀门再启动泵，随后向其他工人解释了操作顺序。','The apprentice quickly grasped why the valve had to close before the pump started, / then explained the sequence / to the rest of the crew.','s1 牢牢抓住；s2 充分理解；s3 把握机会；s4 名词“理解力/紧握”。','理解阀门顺序并向同事解释，体现 grasp s2。'],['The student grasped the concept by remaining unable to explain it, apply it, or recognise it in an example.','The student had not grasped the concept because she could not explain or apply it.','不能解释或应用说明尚未理解，而不是已经 grasped。'],[[1,'To grasp a handle is to?',['take and hold it firmly','look at it without touching','make it disappear'],0,'grasp s1 指牢牢抓住。'],[2,'To grasp a concept is to?',['understand it completely','forget it immediately','copy its title only'],0,'grasp s2 指理解、领会。'],[3,'To grasp an opportunity is to?',['take it eagerly when it appears','reject it without consideration','hide it from everyone'],0,'grasp s3 表示抓住机会。'],[4,'A firm grasp of grammar means?',['strong understanding or command','a physical hand wrapped around a book','a school timetable'],0,'grasp s4 可指掌握、理解力。']]);
P('grass','源自古英语 græs，可指长薄叶的绿色植物、覆盖草地的区域，也可指用作牲畜饲料的草。',[2,'公园养护','The children played on the grass beside the library, while maintenance workers reseeded the worn patches near the benches.','孩子们在图书馆旁的草地上玩耍，养护人员则给长椅附近磨损的斑块重新播种。','The children played on the grass beside the library, / while maintenance workers reseeded the worn patches / near the benches.','s1 指草这种植物；s2 指草地或草坪；s3 指用作饲料的牧草。','孩子在覆盖青草的区域玩耍，体现 grass s2。'],['The sheep were fed grass as paving stones harvested from the field.','The sheep were fed grass as forage cut from the field.','石板不能作为草料喂羊；grass s3 指牧草。'],[[1,'Grass in a field is?',['a green plant with narrow leaves','a hard stone used for a road','a kind of cloud'],0,'grass s1 指草本植物。'],[2,'A patch of grass behind a house is?',['an area covered with grass','one blade held in a hand','a bag of animal feed'],0,'grass s2 指草地或草坪。'],[3,'Farmers may cut grass to use as?',['forage for livestock','a footnote in a book','a metal tool'],0,'grass s3 可指牲畜饲料。'],[1,'Which sentence uses grass as a plant?',['Grass grows quickly after rain.','The children sat on the grass.','The farmer stored grass for winter feed.'],0,'Grass grows 描述草这种植物。']]);
P('grasshopper','由 grass 与 hopper“跳跃者”组成，指后腿有力、善于跳跃的蚱蜢或蝗虫类昆虫。',[1,'昆虫观察','A grasshopper leapt from the dry stalk when the field researcher approached, its powerful hind legs carrying it several metres.','田野研究者靠近时，一只蚱蜢从干茎上跳开，强健的后腿让它跃出数米。','A grasshopper leapt from the dry stalk / when the field researcher approached, / its powerful hind legs carrying it several metres.','可数名词；昆虫，后腿发达，通常通过跳跃移动。','凭借强健后腿跳跃的是 grasshopper。'],['The grasshopper moved through the field by swimming with fins and breathing through gills.','The grasshopper moved through the field by jumping with its powerful hind legs.','蚱蜢是昆虫，不用鳍和鳃；其典型运动方式是跳跃。'],[[1,'A grasshopper is?',['an insect with powerful jumping legs','a small river boat','a grain of wheat'],0,'grasshopper 指蚱蜢或蝗虫类昆虫。'],[1,'How does a grasshopper commonly escape danger?',['it leaps using its hind legs','it grows a shell of granite','it swims under the soil'],0,'强健后腿帮助蚱蜢跳跃逃生。'],[1,'The “hopper” part of grasshopper suggests?',['jumping movement','a school grade','a type of rainfall'],0,'hopper 与跳跃的动作有关。'],[1,'Which habitat might contain grasshoppers?',['a grassy field','a deep ocean trench','a sealed metal furnace'],0,'草地常见蚱蜢。']]);
P('grassland','由 grass 与 land 组成，指以草类为主、树木较少的开阔地带。',[1,'生态保护','The reserve protects native grassland by limiting tree planting and grazing, preserving habitat for ground-nesting birds.','保护区通过限制植树和放牧来保护本土草原，为地面筑巢的鸟类保留栖息地。','The reserve protects native grassland / by limiting tree planting and grazing, / preserving habitat for ground-nesting birds.','可数或集合名词；生态系统以草本植被占主导，树木通常稀少或零散。','开阔区域以草类为主，符合 grassland。'],['The map called a dense tropical forest with a closed canopy and almost no grasses a grassland.','The map called the open prairie with grasses and few trees a grassland.','树冠浓密、几乎无草的森林不是以草类为主的草原。'],[[1,'Grassland is open country dominated by?',['grasses rather than trees','deep water rather than plants','buildings rather than vegetation'],0,'grassland 以草类而非树木为主。'],[1,'Which animal habitat may be grassland?',['open prairie supporting grazing animals','a deep-sea reef','a paved city tunnel'],0,'草原可供食草动物生活。'],[1,'Why might grassland conservation limit tree planting?',['to preserve an ecosystem naturally dominated by grasses','to prevent all plants from growing','to turn the area into a car park'],0,'过度植树会改变草原生态特征。'],[1,'Choose the natural phrase.',['temperate grassland','grassland of an ocean trench','grassland to be a mountain river'],0,'temperate grassland 是常见生态术语。']]);
P('grassy','由 grass 加 -y 构成，可指覆盖着草，也可指草绿色或带有草的味道。',[1,'郊野道路','The hikers followed a grassy track across the meadow, where the soft vegetation kept their boots out of the mud.','徒步者沿着草长得茂密的小径穿过草地，柔软植被让靴子避开了泥泞。','The hikers followed a grassy track across the meadow, / where the soft vegetation / kept their boots out of the mud.','s1 指长满草；s2 指草绿色或有草的味道。','小径表面覆有草，体现 grassy s1。'],['The grassy bank was bare concrete with no vegetation or green colour anywhere.','The paved bank was bare concrete with no vegetation or green colour anywhere.','没有草木的混凝土岸不属长草的 grassy bank。'],[[1,'A grassy slope is?',['covered with grass','made entirely of glass','filled with seawater'],0,'grassy s1 指长草的。'],[2,'A grassy-green paint colour is?',['green like grass','the colour of dry charcoal','bright pink'],0,'grassy s2 可表示草绿色。'],[2,'A drink described as grassy may have?',['a taste reminiscent of fresh grass','a flavour of metal only','no taste in any sense'],0,'grassy 可描述类似青草的味道。'],[1,'Choose the natural phrase.',['a grassy field','grassy to arrive','a grassy of the hill'],0,'grassy 可修饰 field。']]);
P('grate','源自古法语 grater“刮擦、磨碎”，既可作动词表示擦碎食物，也可作名词指覆盖孔洞的金属栅格。',[1,'烹饪','Grate the lemon zest directly over the bowl, stopping before the bitter white pith reaches the cutting board.','把柠檬皮屑直接磨到碗上，注意别磨到苦味的白色内层。','Grate the lemon zest directly over the bowl, / stopping before the bitter white pith / reaches the cutting board.','词条同一来源义项包括动词“磨碎”和名词“金属栅格”；由句法判断词性。','把柠檬皮磨成细屑是 grate 的动词用法。'],['The cook grated the cheese by leaving the block whole and placing it untouched on the counter.','The cook stored the cheese by leaving the block whole and placing it untouched on the counter.','保持整块未处理不是磨碎。'],[[1,'To grate cheese is to?',['rub it against a rough tool to make small pieces','freeze it whole','weigh it without changing it'],0,'动词 grate 指擦碎食物。'],[1,'A fireplace grate is?',['a metal frame that holds fuel or covers an opening','a type of cheese','a school grade'],0,'名词 grate 可指金属炉栅。'],[1,'Which action grates a carrot?',['shredding it with a grater','boiling it whole','painting it green'],0,'擦丝工具可把胡萝卜磨碎。'],[1,'Choose the natural phrase.',['a metal grate over the drain','grate to the drain yesterday','a grate of a bowl of soup'],0,'排水口上的金属栅格是 grate。']]);
P('grateful','由古法语 gré“乐意、感谢”与 -ful 构成，表示感受到帮助或善意后心存谢意，也可用于表达感谢的措辞。',[2,'志愿服务','The residents were grateful for the volunteers’ help, and they wrote a card expressing thanks for the meals delivered during the blackout.','居民感谢志愿者的帮助，并写卡片感谢停电期间送来的餐食。','The residents were grateful for the volunteers’ help, / and they wrote a card / expressing thanks for the meals delivered during the blackout.','s1 指内心感激；s2 可描述表达谢意的言行或令人愉快、可感激的情形。','卡片表达对志愿者帮助的谢意，体现 grateful。'],['The residents were grateful for the meals but complained that they felt no thanks and wanted the volunteers to leave.','The residents were ungrateful for the meals and complained that they felt no thanks.','毫无谢意且抱怨帮助者，不符合 grateful。'],[[1,'A grateful person feels?',['thankful for help or kindness','angry that anyone offered help','certain that no favour occurred'],0,'grateful s1 表示心存感激。'],[2,'A grateful message is one that?',['expresses thanks','threatens the recipient','asks for a refund only'],0,'grateful s2 可指表达谢意的内容。'],[1,'Which reply is grateful?',['“Thank you for staying late to help.”','“Your help meant nothing; leave now.”','silence paired with deliberate insult'],0,'明确致谢表达感激。'],[1,'Choose the natural construction.',['grateful for your support','grateful at the support of','grateful to support yesterday'],0,'常用 be grateful for + 帮助或事物。']]);
P('gratify','源自拉丁语 gratificari“使满意、表示好意”，经法语进入英语，表示使某人满足或高兴。',[1,'个人成就','It gratified the young scientist to see the community use her clean-water test, especially after months of field trials.','看到社区使用她的净水检测方法，年轻科学家感到满足；此前她进行了数月实地试验。','It gratified the young scientist to see the community use her clean-water test, / especially after months of field trials.','及物动词；可接人作宾语，或用 it gratifies someone to do；表示满足愿望或使愉快。','社区采用她的方法使科学家感到欣慰。'],['The result gratified no one because everyone was pleased, satisfied, and eager to celebrate it.','The result gratified everyone because they were pleased and satisfied with it.','让所有人满足就不是“无人感到满足”。'],[[1,'To gratify a wish is to?',['satisfy it','hide it permanently','make it impossible'],0,'gratify 表示满足愿望。'],[1,'Which news might gratify a researcher?',['her method is adopted and helps local families','her data are deleted before review','her work is ignored without explanation'],0,'研究成果产生帮助会使研究者感到满足。'],[1,'Choose the natural construction.',['The gift gratified him.','The gift gratified at him.','The gift gratify to him.'],0,'gratify 可直接接感到满足的人作宾语。'],[1,'A decision gratified the team means it?',['pleased or satisfied them','confused them deliberately','removed their names'],0,'gratify 的核心义是使满意。']]);
P('grating','由 grate 加 -ing 构成，可指覆盖孔洞的金属条格，也可作形容词形容刺耳、令人烦躁的声音或语气。',[1,'城市设施','Leaves collected on the drain grating, so the caretaker lifted the metal cover and cleared the opening before the rain.','树叶堆在排水口格栅上，管理员掀开金属盖并在下雨前清理开口。','Leaves collected on the drain grating, / so the caretaker lifted the metal cover / and cleared the opening before the rain.','s1 可数名词“格栅”；也可作形容词“刺耳的”，修饰 sound、voice、tone。','覆盖排水口的金属条盖是 grating 名词义。'],['The grating sound was soft and soothing, with no harsh or irritating quality.','The gentle sound was soft and soothing, with no harsh or irritating quality.','柔和悦耳不符合 grating 的刺耳义。'],[[1,'A drain grating is?',['a metal grid covering an opening','a warm dessert','a school examination'],0,'grating s1 指金属格栅。'],[1,'A grating voice sounds?',['harsh and irritating','soft and soothing','completely silent'],0,'形容词 grating 表示刺耳。'],[1,'Which object is a grating?',['bars fitted over a floor opening','a bag of flour','a leaf on grass'],0,'覆盖孔洞的条栅是 grating。'],[1,'Choose the natural phrase.',['a grating noise from the brakes','a grating of gratitude','grating to eat slowly'],0,'grating 可修饰 noise，表示刺耳。']]);
P('gratis','源自拉丁语 gratis“出于好意、免费”，是副词或形容词，表示无需付款。',[1,'公共服务','The museum offers audio guides gratis on family days, so visitors can borrow a device without paying an additional fee.','博物馆在家庭日免费提供语音导览，游客无需额外付费即可借用设备。','The museum offers audio guides gratis on family days, / so visitors can borrow a device / without paying an additional fee.','较正式用法，意为免费；常用于服务或商品，语气比 free 稍书面。','游客无需付费借设备，体现 gratis。'],['The museum offered the guide gratis but charged every visitor a required fee before borrowing it.','The museum offered the guide for a fee and charged every visitor before borrowing it.','要求付费就不是 gratis。'],[[1,'An item provided gratis is?',['free of charge','sold at a higher price','available only after a loan'],0,'gratis 表示免费提供。'],[1,'Which offer is gratis?',['a free repair with no payment required','a repair with a compulsory fee','a repair available only to paying members'],0,'无需付款的服务是 gratis。'],[1,'“The samples are supplied gratis” means?',['the samples are supplied at no cost','the samples are delivered late','the samples must be returned immediately'],0,'gratis 表示不收费。'],[1,'Choose the natural sentence.',['The guide is available gratis.','The guide is gratis of a fee to pay.','Gratis the guide is a fee.'],0,'available gratis 是自然表达。']]);
P('gratitude','源自拉丁语 gratitudo“感谢之情”，经法语进入英语，指感受到恩惠后的感激，也可指向某人表达的谢意。',[2,'医疗照护','After the nurse found a pharmacy open at night, the family sent her a note of gratitude for staying until the medicine arrived.','护士找到一家夜间营业的药房后，家人在药品送到前一直陪她，并给她写了感谢信。','After the nurse found a pharmacy open at night, / the family sent her a note of gratitude / for staying until the medicine arrived.','不可数名词；s1 指内心感激，s2 指向某人表达的谢意；常用 gratitude for/to。','家人写信感谢护士的帮助，体现 gratitude s2。'],['The family showed gratitude by denying that the nurse had helped and refusing to acknowledge her effort.','The family showed ingratitude by denying that the nurse had helped.','否认帮助、不承认付出是 ingratitude，不是 gratitude。'],[[1,'Gratitude is a feeling of?',['thankfulness for help or kindness','anger at receiving assistance','uncertainty about a measurement'],0,'gratitude s1 指感激之情。'],[2,'A note of gratitude is?',['a message expressing thanks','a request for a refund','a warning about danger'],0,'gratitude s2 可指表达谢意。'],[1,'Which action shows gratitude?',['thanking a neighbour who cared for your dog','claiming the neighbour did nothing','demanding more help without acknowledgement'],0,'承认并感谢帮助体现感激。'],[1,'Choose the natural phrase.',['gratitude to the volunteers','gratitude at the volunteers their address','gratitude the bridge'],0,'常用 gratitude to someone。']]);
P('gratuitous','源自拉丁语 gratuitus“无报酬的、自愿的”，经法语进入英语；可指无正当理由、尤其无谓暴力，也可指免费提供。',[1,'内容审核','The editor removed gratuitous violence from the film because the graphic scenes did not advance the story or serve any clear purpose.','编辑删去了影片中无谓的暴力，因为那些血腥场景既不推动剧情，也没有明确作用。','The editor removed gratuitous violence from the film / because the graphic scenes did not advance the story / or serve any clear purpose.','s1 指无正当理由、无必要的行为或批评；s2 指免费提供。','与剧情无关且无明确目的的暴力属于 gratuitous s1。'],['The gratuitous criticism was carefully supported by relevant evidence and necessary to correct a dangerous factual error.','The justified criticism was supported by relevant evidence and necessary to correct a factual error.','有证据且为纠正危险错误所必需的批评并非无缘无故。'],[[1,'Gratuitous violence is?',['violence included without a good reason or purpose','violence required to stop immediate danger','a precise description of safety rules'],0,'gratuitous s1 指不必要、无正当理由的暴力。'],[2,'A gratuitous service is?',['provided without charge','available only at a high price','given as a punishment'],0,'gratuitous s2 表示免费提供。'],[1,'Which comment is gratuitous?',['an insulting remark unrelated to the task','a necessary warning about a real hazard','a correction supported by evidence'],0,'无关且无必要的侮辱属于 gratuitous。'],[1,'Does gratuitous always mean free?',['No; it can mean needless or unjustified.','Yes; it never describes behaviour.','No; it means extremely expensive.'],0,'该词另有“无理由、不必要”的常见义。']]);
P('gratuity','源自拉丁语 gratuitus“自愿给予的”，经法语进入英语，现代常指顾客给服务人员的小费。',[1,'餐饮服务','The customer left a gratuity for the server after the meal, following the restaurant’s guidance that tipping was optional.','顾客用餐后给服务员留了小费，餐厅说明是否给小费由顾客自愿决定。','The customer left a gratuity for the server after the meal, / following the restaurant’s guidance / that tipping was optional.','可数名词；常见 leave/pay a gratuity，指服务后额外给服务人员的钱。','顾客在账单之外自愿给的钱是 gratuity。'],['The restaurant called the server’s hourly salary a gratuity even though it was required pay from the employer.','The restaurant called the extra voluntary tip a gratuity.','雇主支付的固定工资不是顾客额外给的小费。'],[[1,'A gratuity is usually?',['money given to a service worker as an extra tip','a mandatory tax on every house','a school grade'],0,'gratuity 指小费。'],[1,'A customer leaves a gratuity when the customer?',['gives extra money for service','refuses to pay the bill','buys a kitchen table'],0,'自愿额外给服务者的钱是 gratuity。'],[1,'Which phrase is natural?',['leave a gratuity','gratuity the menu','gratuity at the restaurant loudly'],0,'常说 leave a gratuity。'],[1,'A gratuity is distinct from a salary because it is often?',['an extra amount given by the customer','the employee’s required base wage','a loan from the bank'],0,'小费通常是工资之外的额外给付。']]);
P('grave','名词 grave 源自古英语 græf“挖出的坑”，指埋葬死者的墓穴；形容词 grave 经古法语源自拉丁语 gravis“沉重、严重”。',[1,'墓园考古','Archaeologists found a stone marker beside the grave, then recorded the burial site before beginning any excavation.','考古学家在墓穴旁发现石碑，并在开始挖掘前记录了墓地位置。','Archaeologists found a stone marker beside the grave, / then recorded the burial site / before beginning any excavation.','s1 名词“墓穴”；s2 形容情况严重；s3 形容举止严肃庄重，属不同词义类别。','石碑旁的埋葬地点是 grave 名词义。'],['The patient’s grave symptoms were mild and unimportant, requiring no medical attention or monitoring.','The patient’s minor symptoms were mild and unimportant, requiring no special monitoring.','轻微、不令人担忧的症状不称 grave。'],[[1,'A grave is?',['a place in the ground where someone is buried','a school report card','a type of fruit'],0,'grave s1 指墓穴。'],[2,'A grave danger is?',['serious and worrying','minor and harmless','a pleasant surprise'],0,'grave s2 表示严重。'],[3,'A grave expression is?',['serious and solemn','playful and giggling','uninterested in every topic'],0,'grave s3 描述严肃庄重的神情。'],[2,'Which situation is grave?',['a bridge has a serious structural crack','a cup has a tiny harmless scratch','a meeting starts five minutes late'],0,'可能导致坍塌的结构裂缝是严重问题。']]);
P('gravel','源自古法语 grave“沙砾、海岸沉积物”，指用于道路或小径的细小石块；也可形容声音粗哑刺耳。',[1,'道路施工','The crew spread gravel over the muddy path, creating a firm surface that would drain water and remain passable after rain.','施工人员在泥泞小路上铺碎石，形成排水良好、雨后仍可通行的坚实路面。','The crew spread gravel over the muddy path, / creating a firm surface / that would drain water and remain passable after rain.','s1 为路面用小石子；s2 比喻声音粗糙、沙哑。','用于铺路的碎小石块是 gravel s1。'],['The path was covered with gravel, meaning it had a soft liquid surface that could not contain any stones.','The path was covered with gravel, meaning it had a surface of small stones.','gravel 是小石块，不是液体。'],[[1,'Gravel is?',['small stones used for paths or roads','a kind of soft bread','a written note at a page’s foot'],0,'gravel s1 指铺路碎石。'],[2,'A gravelly voice sounds?',['rough and harsh','smooth and musical','completely silent'],0,'gravel s2 描述粗哑声音。'],[1,'Why put gravel on a garden path?',['it creates a drainable surface of small stones','it turns the path into grass','it feeds birds directly'],0,'碎石路面有助于排水。'],[2,'Which description is gravelly?',['his voice rasped after the long speech','her voice was clear and soft','the room was silent'],0,'沙哑粗糙的嗓音可称 gravelly。']]);
P('graveyard','由 grave 与 yard 组成，指安葬死者的墓地。',[1,'社区历史','The old graveyard behind the chapel contains headstones from several centuries, and volunteers are mapping each plot before restoration.','小教堂后面的老墓地有数百年来的墓碑，志愿者正在修复前绘制每个墓穴的位置图。','The old graveyard behind the chapel contains headstones from several centuries, / and volunteers are mapping each plot / before restoration.','可数名词；安葬死者的场所，常位于教堂附近或社区内。','墓碑和墓穴构成 graveyard。'],['The village called its playground a graveyard because children used it daily and no one was buried there.','The village called the burial ground beside the church a graveyard.','有人日常玩耍且没有埋葬者的游乐场不是墓地。'],[[1,'A graveyard is?',['a place where the dead are buried','a school playground','a grain store'],0,'graveyard 指墓地。'],[1,'Which feature is common in a graveyard?',['headstones marking burial plots','a runway for aircraft','a river crossing'],0,'墓碑常标记墓穴。'],[1,'Why might historians map an old graveyard?',['to document burial plots and preserve local history','to find a route for a new airport','to grade school essays'],0,'墓地记录可保护地方历史。'],[1,'Choose the natural phrase.',['a quiet graveyard beside the chapel','a graveyard full of swimming pools','graveyard the fence quickly'],0,'墓地可位于教堂旁。']]);
P('gravitas','源自拉丁语 gravitas“分量、庄重”，来自 gravis“沉重”，现代指使人显得严肃可信、赢得尊重的气度。',[1,'公共演讲','The judge’s gravitas quieted the courtroom, and her measured questions made both lawyers treat the evidence with care.','法官庄严的气度使法庭安静下来；她审慎的提问让双方律师认真对待证据。','The judge’s gravitas quieted the courtroom, / and her measured questions / made both lawyers treat the evidence with care.','不可数名词；描述严肃、有分量并令人尊重的气质，不等于严厉或生气。','法官的庄重举止使法庭肃静，符合 gravitas。'],['The speaker’s gravitas made the audience laugh because he behaved like a silly clown throughout the solemn ceremony.','The speaker’s frivolity made the audience laugh because he behaved like a silly clown throughout the solemn ceremony.','庄严仪式上的滑稽举止体现轻浮，不是 gravitas。'],[[1,'A person with gravitas is likely to?',['seem serious and worthy of respect','behave carelessly for attention','avoid every responsibility'],0,'gravitas 指庄重而有分量的气质。'],[1,'Which speaker shows gravitas?',['a calm chair who listens carefully before making a decision','a person who mocks every participant','a speaker who changes claims every minute'],0,'认真倾听和审慎决定会给人以庄重可信之感。'],[1,'Gravitas does not simply mean?',['being angry or severe','having a serious, respected presence','speaking with authority'],0,'有分量的庄重气度不等于愤怒或严厉。'],[1,'Choose the natural phrase.',['the gravitas of a senior judge','gravitas to eat a bowl','gravitas at the green grass'],0,'gravitas 常描述某人的庄重气度。']]);
P('gravitation','源自拉丁语 gravitatio，来自 gravitas“重量”，指物体间引力，也可比喻向某处或某种选择的倾向。',[1,'物理学','The lesson demonstrated gravitation by showing how the Moon’s motion and Earth’s pull keep the satellite in orbit.','课程用月球运动与地球引力如何使卫星留在轨道上来演示万有引力。','The lesson demonstrated gravitation / by showing how the Moon’s motion and Earth’s pull / keep the satellite in orbit.','s1 指物体相互吸引的力；s2 指人或事物向某方向聚拢的倾向。','地球吸引卫星并影响其轨道，体现 gravitation s1。'],['The team’s gravitation toward the new office meant nobody felt drawn to it and everyone moved away.','The team’s aversion to the new office meant nobody felt drawn to it and everyone moved away.','聚拢或倾向某处与远离、厌恶相反。'],[[1,'Gravitation is the force that?',['attracts objects toward one another','pushes every object away equally','turns mass into sound'],0,'gravitation s1 指物体之间的引力。'],[2,'A gravitation toward city centres describes?',['a tendency for people or activity to move there','the force that keeps planets in orbit only','a refusal to approach them'],0,'s2 比喻表示向某处或某种事物聚拢。'],[1,'Why does a satellite remain in orbit around Earth?',['gravitation helps pull it toward Earth while it moves forward','there is no force acting on it','the Moon holds it with a rope'],0,'引力参与维持卫星轨道运动。'],[2,'The graduates’ gravitation toward public service means they?',['are increasingly drawn to that field','are forced away from every job','have completed a gravity experiment'],0,'此处 gravitation 表示一种趋向。']]);
P('gravitational','由 gravitation 加 -al 构成，指由引力造成或与引力有关的。',[1,'天体物理','A gravitational force from the nearby planet altered the spacecraft’s path, requiring mission control to adjust its planned trajectory.','附近行星的引力改变了航天器轨迹，任务控制中心因此需要调整计划航线。','A gravitational force from the nearby planet altered the spacecraft’s path, / requiring mission control / to adjust its planned trajectory.','形容词；常修饰 force、field、wave，表示由引力导致或相关。','行星引力使航天器偏航，属于 gravitational force。'],['The gravitational effect changed the spacecraft’s path even though the planet exerted no gravity or attraction at all.','The aerodynamic effect changed the spacecraft’s path as it passed through a planetary atmosphere.','若变化来自大气阻力，应称空气动力效应，而非重力效应。'],[[1,'A gravitational force is related to?',['the attraction associated with mass','a person’s gratitude','a type of grass'],0,'gravitational 指与引力相关。'],[1,'Gravitational waves are associated with?',['changes or disturbances in gravity','sound from a musical instrument only','the growth of plants'],0,'引力波属于引力现象。'],[1,'Which event is gravitational?',['a planet’s pull alters a moon’s orbit','wind pushes a sailboat','a magnet attracts iron'],0,'行星对卫星的吸引是引力作用。'],[1,'Choose the natural phrase.',['a gravitational field','a grateful field','a gravitating field of grass'],0,'gravitational 常修饰 field。']]);
P('gravity','源自拉丁语 gravitas“重量、严肃性”，来自 gravis“沉重”；可指引力、情况严重性或举止庄重。',[2,'事故调查','The inspector stressed the gravity of the bridge damage, explaining that even a small crack could lead to a dangerous collapse.','检查员强调桥梁受损的严重性，解释说即使小裂缝也可能造成危险坍塌。','The inspector stressed the gravity of the bridge damage, / explaining that even a small crack / could lead to a dangerous collapse.','s1 指物体受地球等吸引；s2 指问题严重性；s3 指人的严肃庄重。','可能导致坍塌的裂缝说明损坏后果严重，体现 gravity s2。'],['The gravity of the safety failure was trivial because nobody could be harmed and no damage was possible.','The seriousness of the safety failure was significant because people could be harmed.','可能造成人员伤害的问题不应称轻微；此处强调严重性。'],[[1,'Gravity keeps objects near Earth because it?',['pulls them toward the planet','makes them weightless everywhere','changes their colour'],0,'gravity s1 指地球的引力。'],[2,'The gravity of a medical emergency is its?',['seriousness and potential consequences','physical weight in kilograms','distance from the hospital'],0,'gravity s2 表示情况的严重程度。'],[3,'A person who speaks with gravity behaves?',['seriously and solemnly','in a joking and careless way','without paying attention'],0,'gravity s3 指庄重严肃的举止。'],[2,'Which matter has great gravity?',['a chemical leak threatening a town’s water supply','a harmless typo on a draft menu','a chair moved to another desk'],0,'威胁饮水安全的泄漏后果重大。']]);
P('gravy','经中古英语与古法语相关词形进入英语，常指烹肉汁液制成的热酱汁；历史词源细节不完全确定。',[1,'家庭烹饪','After roasting the turkey, Rosa poured the pan juices into a saucepan and whisked them into gravy for the meal.','烤完火鸡后，罗莎把烤盘肉汁倒入小锅搅匀，做成配餐的肉汁酱。','After roasting the turkey, / Rosa poured the pan juices into a saucepan / and whisked them into gravy for the meal.','不可数名词；常用作肉类、土豆等的热酱汁；不同地区配方会有差异。','烤肉汁液制成并浇在餐食上的酱汁是 gravy。'],['The cook served gravy as a dry block of stone that could not be poured over the food.','The cook served gravy as a warm sauce made from the meat juices.','gravy 是酱汁，不是石块。'],[[1,'Gravy is?',['a sauce often made from meat juices','a kind of tablecloth','a school grade'],0,'gravy 指肉汁或肉汁酱。'],[1,'What might be poured over roast potatoes?',['gravy','graphite','grass seed'],0,'肉汁酱常搭配烤肉和土豆。'],[1,'Pan drippings can be used to make?',['gravy','a greenhouse','a footnote'],0,'烤盘肉汁可用来制作 gravy。'],[1,'Choose the natural phrase.',['pour gravy over the roast','gravy the roast into a page','a gravy of the fork'],0,'gravy 可浇在烤肉上。']]);
P('gray','源自古英语 græg，受古诺斯语同源词影响；gray 是美式拼写，英式常写 grey，可指颜色、灰白头发、阴郁或灰色衣物。',[2,'人物描写','After decades outdoors, the gardener’s hair had turned gray, though she still worked in the greenhouse every morning.','多年在户外工作后，园丁的头发变灰白了，但她仍每天早晨在温室里工作。','After decades outdoors, the gardener’s hair had turned gray, / though she still worked / in the greenhouse every morning.','s1 灰色；s2 头发灰白；s3 阴郁单调；s4 灰色或灰色衣物。gray 为美式拼写。','头发变灰白，体现 gray s2。'],['The gray-haired gardener had bright red hair with no grey or white strands.','The red-haired gardener had bright red hair with no grey or white strands.','没有灰白头发的人不符合 gray-haired。'],[[1,'A gray cloud is?',['between black and white in colour','bright green','made of wood'],0,'gray s1 指黑与白之间的灰色。'],[2,'Someone whose hair turns gray has?',['hair that has become grey-white','hair that is naturally blue','no hair at all'],0,'gray s2 描述灰白头发。'],[3,'A gray, uneventful day may feel?',['dull and without interest','exciting and full of hope','hot and tropical'],0,'gray s3 可比喻单调阴郁。'],[4,'In “the soldiers wore gray,” gray refers to?',['grey-coloured clothing','a school grade','a hair treatment'],0,'gray s4 可作名词指灰色衣物。']]);
P('graze','源自古英语 græsian“吃草”，词义扩展为擦伤皮肤或擦过表面；可作动词，也可指轻微擦伤。',[1,'牧场管理','The sheep graze on the hillside during the day, while the shepherd checks the fence and refills their water trough.','羊群白天在山坡上吃草，牧羊人则检查围栏并给水槽添水。','The sheep graze on the hillside during the day, / while the shepherd checks the fence / and refills their water trough.','s1 动物吃草或放牧；s2 皮肤擦伤；s3 轻轻擦过；s4 名词“擦伤”。','羊群在山坡上取食青草，体现 graze s1。'],['The sheep grazed on the hillside by flying above the grass without eating any plants.','The sheep grazed on the hillside by eating the grass there.','飞过而不取食不属于吃草或放牧。'],[[1,'Cattle graze when they?',['eat grass in a field','repair a fence','store grain in a barn'],0,'graze s1 指动物吃草。'],[2,'She grazed her knee when she?',['scraped the skin slightly in a fall','broke the bone completely','washed the skin gently'],0,'graze s2 指皮肤表面轻微擦伤。'],[3,'The car grazed the wall means it?',['touched it lightly while moving past','crashed through it completely','stopped far away from it'],0,'graze s3 指移动中轻轻擦过。'],[4,'A graze on the elbow is?',['a slight surface injury','a deep broken bone','a type of grass seed'],0,'graze s4 是轻微擦伤。']]);
P('grease','源自古法语 graisse“动物脂肪”，来自 gras“肥的”；可指动物油脂、机械润滑脂，也可作动词表示涂油润滑。',[2,'设备维护','Apply a small amount of grease to the bearing so the moving parts turn smoothly without metal grinding against metal.','在轴承上涂少量润滑脂，使活动部件顺畅转动，避免金属互相磨擦。','Apply a small amount of grease to the bearing / so the moving parts turn smoothly / without metal grinding against metal.','s1 动物脂肪或厚油；s2 机械润滑脂；s3 作动词表示涂抹油脂。','轴承上的润滑剂减少摩擦，体现 grease s2。'],['The mechanic greased the bearing by washing away every lubricant and leaving the metal surfaces dry.','The mechanic cleaned the bearing by washing away the lubricant and leaving the metal surfaces dry.','去除油脂使表面干燥是清洁，不是涂油润滑。'],[[1,'Grease from cooking may be?',['soft animal fat or thick oil','a dry piece of paper','a school report'],0,'grease s1 指动物脂肪或厚油。'],[2,'A mechanic uses grease to?',['lubricate moving parts','make a metal joint louder','weigh a vehicle'],0,'机械润滑脂能减少部件摩擦。'],[3,'To grease a hinge is to?',['put lubricant on it','remove every moving part','paint it with water'],0,'grease s3 作动词表示涂油。'],[2,'Which phrase is natural?',['apply grease to the bearing','grease at the bearing','grease the bearing of gratitude'],0,'可以将润滑脂涂到轴承上。']]);
P('greasy','由 grease 加 -y 构成，可指覆盖油脂，也可批评一个人虚假热情、令人不舒服地谄媚。',[1,'厨房卫生','The greasy pan needed hot water and detergent because a thick film of oil covered its bottom after frying.','煎炸后锅底覆着厚厚油膜，因此这只油腻的锅需要用热水和洗涤剂清洗。','The greasy pan needed hot water and detergent / because a thick film of oil covered its bottom / after frying.','s1 指沾油；s2 贬义形容人虚假亲热、油滑谄媚。','锅底覆盖油膜，体现 greasy s1。'],['The pan was greasy because its surface had been thoroughly degreased and felt completely dry.','The pan was clean because its surface had been thoroughly degreased and felt completely dry.','去油后干净干燥的锅不再 greasy。'],[[1,'A greasy surface is?',['covered with oil or fat','completely dry and clean','made of dry paper'],0,'greasy s1 指表面沾有油脂。'],[2,'A greasy salesperson may seem?',['falsely friendly in an unpleasant way','honest and straightforward','silent and shy'],0,'greasy s2 比喻令人不适的虚假热情。'],[1,'Which object is greasy?',['a plate with oily residue','a freshly washed dry glass','a clean cotton towel'],0,'有油性残留的盘子是 greasy。'],[2,'Why might a character be called greasy?',['their friendliness feels insincere and manipulative','they have grease on a frying pan','they speak clearly and honestly'],0,'该比喻义批评一个人油滑、不真诚。']]);
P('great','源自古英语 great“大的、重要的”，可形容伟大重要、数量巨大、体验极好、技能出众，也可作名词指伟人。',[4,'棋艺','Mira is great at chess, and her patient endgame play has helped the school team win several regional tournaments.','米拉很擅长下棋；她耐心的残局技巧帮助校队赢得了几场地区比赛。','Mira is great at chess, / and her patient endgame play / has helped the school team win several regional tournaments.','s1 伟大重要；s2 数量或程度大；s3 极好；s4 擅长；s5 名词“伟人、名人”。需由上下文判义。','great at chess 表示在棋艺方面很擅长，体现 s4。'],['The discovery was a great advance but had no importance, even though it prevented a disease that had killed millions.','The discovery was a great advance and had major importance because it prevented a disease that had killed millions.','预防曾致数百万人死亡的疾病具有重大意义，不能说毫无重要性。'],[[1,'A great achievement is?',['important and admired','small and insignificant','a quantity of gravy'],0,'great s1 指重要而值得称赞。'],[2,'A great amount of rainfall means?',['a very large amount','almost no rain','rain that is perfectly warm'],0,'great s2 可表示数量很大。'],[3,'“We had a great time” means?',['we enjoyed ourselves very much','we were bored throughout','we measured the clock'],0,'great s3 表示极好、令人愉快。'],[5,'The “greats” of jazz are?',['famous or important jazz figures','new students in a classroom','small amounts of music'],0,'great s5 作名词指杰出人物。']]);
P('greater','由 great 加比较级后缀 -er 构成，表示比另一对象更大、更多或程度更高。',[1,'资源比较','The second battery stores greater energy than the first, allowing the field sensor to operate through longer winter nights.','第二块电池储存的能量更多，因此野外传感器能在冬夜运行更久。','The second battery stores greater energy than the first, / allowing the field sensor to operate / through longer winter nights.','比较级形容词，通常与 than 连用；greater 可比较数量、规模、程度或重要性。','储能比第一块多，体现 greater 的比较意义。'],['The second battery stored greater energy than the first because it held less power and ran for a shorter time.','The second battery stored less energy than the first because it held less power and ran for a shorter time.','能量更少、运行更短时应说 less，而非 greater。'],[[1,'Greater means?',['larger or more than something else','the smallest of all','exactly equal in every way'],0,'greater 是 great 的比较级。'],[1,'Which has greater capacity?',['a tank holding 80 litres compared with one holding 50','two tanks holding 50 litres each','an empty tank compared with a full one'],0,'80升容量大于50升。'],[1,'Choose the standard comparison.',['greater than the previous amount','greater of the previous amount','greater to the previous amount'],0,'比较级常用 greater than。'],[1,'A greater concern is?',['a more important worry','a worry that has disappeared','a measurement of grass'],0,'greater 可表示程度或重要性更高。']]);
P('greatest','由 great 的最高级形式构成，表示在一组对象中最大、最高或最重要。',[1,'体育记录','She set the greatest distance in the competition, passing the previous record by more than two metres.','她在比赛中创造了最远成绩，超过原纪录两米多。','She set the greatest distance in the competition, / passing the previous record / by more than two metres.','形容词最高级；比较范围通常由 in、of 或上下文说明。','在所有选手中距离最远，体现 greatest。'],['The greatest score in the tournament was the lowest of every player and fell below the record.','The lowest score in the tournament was below every player’s score record.','greatest 指最大或最高，不能表示最低分。'],[[1,'The greatest value in a set is?',['the largest one','the smallest one','the value that was never measured'],0,'greatest 是 great 的最高级。'],[1,'Who achieved the greatest height?',['the climber who reached the highest point','the climber who stopped at the base','the climber who never started'],0,'最高点对应 greatest height。'],[1,'Choose the natural phrase.',['the greatest of the three proposals','the greatest than the others','greatest to compare it'],0,'最高级可用 of + 范围。'],[1,'A team’s greatest victory is its?',['most important or impressive win','least successful match','next scheduled practice'],0,'greatest 可表示最重要或最值得称道的。']]);
P('greatly','由 great 加副词后缀 -ly 构成，表示程度很高或变化幅度很大。',[1,'社区影响','The new bus route greatly improved access to the hospital, especially for residents who had previously needed two transfers.','新的公交线路大大改善了前往医院的交通，尤其方便了此前需要换乘两次的居民。','The new bus route greatly improved access to the hospital, / especially for residents / who had previously needed two transfers.','副词，修饰 improved、increased、appreciate 等；表示程度或影响显著。','新线路显著改善交通便利性，体现 greatly。'],['The new bus route greatly changed nothing, leaving every journey and transfer exactly as before.','The new bus route barely changed anything, leaving every journey and transfer almost as before.','完全没有改变不能说 greatly changed。'],[[1,'If access improved greatly, it improved?',['by a large amount','not at all','only in colour'],0,'greatly 表示程度显著。'],[1,'Which sentence uses greatly naturally?',['The repair greatly reduced noise.','The repair greatly on Monday.','Greatly the repair was a road.'],0,'greatly 修饰 reduced。'],[1,'A greatly appreciated gift is?',['very much appreciated','not noticed at all','measured in kilograms'],0,'greatly 可加强 appreciate 的程度。'],[1,'“Costs increased greatly” means costs?',['rose substantially','stayed exactly the same','fell to zero'],0,'greatly 指增长幅度很大。']]);
P('Greece','经拉丁语 Graecia 进入英语，指欧洲南部国家希腊，也可指古希腊文明。',[1,'地理','Greece lies in southeastern Europe and includes a mainland peninsula and many islands in the Aegean and Ionian seas.','希腊位于欧洲东南部，包括大陆半岛以及爱琴海和爱奥尼亚海中的许多岛屿。','Greece lies in southeastern Europe / and includes a mainland peninsula / and many islands in the Aegean and Ionian seas.','专有名词，首字母大写；s1 指现代国家，s2 指古代希腊文明。','此处描述现代国家的地理位置，体现 Greece s1。'],['The museum called the modern state of Greece an ancient civilization that ended before the classical era began.','The museum called ancient Greece a civilization that flourished in antiquity.','现代国家与古代文明是相关但不同的指称，注意区分。'],[[1,'Greece is?',['a country in southeastern Europe','a city in South America','a type of metric unit'],0,'Greece s1 指现代欧洲国家。'],[2,'Ancient Greece is associated with?',['classical philosophy and the ancient Olympic Games','the invention of the greenhouse','modern traffic signs only'],0,'s2 指古希腊文明。'],[1,'The Aegean islands belong to the geography of?',['Greece','Greenland','Graham'],0,'许多爱琴海岛屿属于希腊。'],[2,'A book on ancient Greece might discuss?',['classical city-states and philosophy','current Greek tourist taxes only','how to measure a gram'],0,'古希腊文明包括城邦与哲学传统。']]);
P('greed','源自古英语 grædig“贪婪的”，与 greedy 同源，可指对财富、食物或权力的强烈自私欲望。',[3,'企业伦理','The inquiry blamed the collapse partly on greed for control, as executives concealed risks to secure greater power and bonuses.','调查部分归因于对控制权的贪欲：高管隐瞒风险以谋取更大权力和奖金。','The inquiry blamed the collapse partly on greed for control, / as executives concealed risks / to secure greater power and bonuses.','不可数名词；s1 泛指自私贪求；s2 特指贪吃；s3 可指对权力或财物的贪欲。','隐瞒风险以获取权力和奖金体现 greed s3。'],['The executives showed no greed because they refused every bonus, shared authority, and disclosed all risks.','The executives showed restraint because they refused bonuses, shared authority, and disclosed risks.','拒绝奖金并共享权力与自私贪求相反。'],[[1,'Greed is?',['an intense selfish desire for more than one needs','a feeling of gratitude','a careful plan to share fairly'],0,'greed s1 指贪得无厌的自私欲望。'],[2,'Greed for food may lead someone to?',['eat far more than needed','refuse all meals','plant trees in a greenhouse'],0,'greed s2 指贪吃。'],[3,'Greed for power is a desire to?',['gain more control for oneself','give authority away','avoid all leadership roles'],0,'greed s3 指对权力的贪欲。'],[1,'Which behaviour suggests greed?',['taking extra resources while others have none','sharing supplies fairly','declining an unnecessary reward'],0,'为了自己拿走过多资源体现贪婪。']]);
P('greedy','由 greed 加 -y 构成，表示想得到超过所需的东西，也可指吃得过多。',[2,'餐桌礼仪','The child was greedy for dessert and took a second slice before checking whether the other guests had received any.','孩子贪吃甜点，没确认其他客人是否拿到，就先拿了第二块。','The child was greedy for dessert / and took a second slice / before checking whether the other guests had received any.','s1 指贪求超过所需；s2 指贪吃。常用 greedy for。','未顾及他人便多拿甜点，体现 greedy s2。'],['The diners were greedy for dessert because they shared one small slice equally and declined any extra servings.','The diners were considerate about dessert because they shared one small slice and declined extra servings.','公平分享且拒绝多拿不表现贪吃。'],[[1,'A greedy person wants?',['more than they need or fairly share','only exactly what they require','to give everything away'],0,'greedy s1 指贪求过多。'],[2,'A greedy eater may?',['take more food than they need','refuse to taste any food','cook dinner for others'],0,'greedy s2 指贪吃。'],[1,'Which action is greedy?',['keeping all the shared supplies for oneself','dividing supplies fairly','asking what each person needs'],0,'独占共享资源体现贪求。'],[2,'Choose the natural phrase.',['greedy for sweets','greedy at to eat','greedy of the dinner'],0,'常用 greedy for + 想要的东西。']]);
P('green','源自古英语 grēne“绿色的”，可指颜色、未成熟、环保立场、缺乏经验，也可作名词指草坪或绿色。',[3,'环保政策','The council approved a green transport plan that adds cycle lanes and electric buses to reduce pollution in the town centre.','市议会批准了绿色交通计划，增设自行车道和电动公交以减少市中心污染。','The council approved a green transport plan / that adds cycle lanes and electric buses / to reduce pollution in the town centre.','s1 颜色；s2 未成熟；s3 环保；s4 缺乏经验；s5 名词指绿色或草地。','减污交通计划体现 green s3 的环保义。'],['The green transport plan increased pollution deliberately and removed buses to make the air dirtier.','The polluting transport plan increased pollution and removed buses.','主动增加污染的计划不是环保的 green plan。'],[[1,'A green leaf is?',['the colour of grass or leaves','a ripe red fruit','a piece of granite'],0,'green s1 指绿色。'],[2,'A green banana is?',['not yet ripe','environmentally friendly','a golf course'],0,'green s2 表示未成熟。'],[4,'A green employee may be?',['inexperienced or naive','a veteran with decades of experience','a plant growing in soil'],0,'green s4 比喻缺乏经验。'],[5,'In “the children played on the village green,” green is?',['an area of grass','a colour adjective only','an unripe fruit'],0,'green s5 作名词指草坪或公共绿地。']]);
P('greenback','由 green 与 back 组成的美式俚语，指美国纸币，因纸币背面传统上印有绿色而得名。',[1,'货币收藏','The collector identified the worn greenback as a one-dollar bill and placed it in a sleeve to protect its ink.','收藏者认出这张旧美元纸币面额为一美元，并把它放入保护套以保护油墨。','The collector identified the worn greenback as a one-dollar bill / and placed it in a sleeve / to protect its ink.','可数名词，美式非正式说法，指美国纸币；不专指某一面额。','被收藏的美元纸币就是 greenback。'],['The cashier called a Canadian coin a greenback because it was a paper banknote issued by the United States.','The cashier called a U.S. paper dollar a greenback.','加拿大硬币不是美国纸币。'],[[1,'A greenback is?',['a U.S. paper banknote','a Greek coin from antiquity','a green leaf'],0,'greenback 指美国纸币。'],[1,'Why was the term greenback used for U.S. notes?',['their backs were traditionally printed in green','they were made from leaves','they were issued only in Greece'],0,'名称与美元纸币背面的绿色印刷有关。'],[1,'Which object could a collector call a greenback?',['a worn American dollar bill','a British copper coin','a plant leaf'],0,'greenback 是美国纸钞的俚语。'],[1,'Choose the natural phrase.',['pay with a greenback','plant a greenback in a garden','a greenback of grass'],0,'可用 greenback 指美国钞票。']]);
P('greenery','由 green 加 -ery 构成，统称绿色植物和叶片。',[1,'室内布置','The lobby’s greenery includes ferns and climbing plants that soften the concrete walls and improve the room’s appearance.','大厅里的绿色植物包括蕨类和藤本植物，柔化了混凝土墙面，也改善了空间观感。','The lobby’s greenery includes ferns and climbing plants / that soften the concrete walls / and improve the room’s appearance.','不可数集合名词；指绿色植物、枝叶或装饰性植被。','蕨类和藤本植物合称 greenery。'],['The lobby’s greenery consisted entirely of grey concrete and contained no plant or leaf.','The lobby’s stonework consisted of grey concrete and contained no plants.','没有植物的混凝土不属于 greenery。'],[[1,'Greenery refers to?',['green plants and leaves','a banknote','a school grade'],0,'greenery 指绿色植物和枝叶。'],[1,'Which room has more greenery?',['one with ferns and potted plants','one with only bare walls','one with a gravel floor and no plants'],0,'蕨类和盆栽属于 greenery。'],[1,'A decorator may add greenery to?',['make an indoor space feel livelier','remove all leaves from a garden','increase a room’s concrete content'],0,'植物可用于室内装饰。'],[1,'Choose the natural phrase.',['lush greenery around the courtyard','greenery to eat a footnote','a greenery of metal tools'],0,'lush greenery 是自然搭配。']]);
P('greenhouse','由 green 与 house 组成，指加热或控温、用玻璃等围护起来培育植物的建筑；也可作定语表示温室气体或效应相关。',[1,'园艺','The nursery keeps tropical seedlings in a heated greenhouse, where staff control humidity and ventilation during cold months.','苗圃把热带幼苗放在加热温室里，寒冷月份由员工调节湿度和通风。','The nursery keeps tropical seedlings in a heated greenhouse, / where staff control humidity and ventilation / during cold months.','s1 为栽培植物的控温建筑；s2 作定语可见于 greenhouse gas/effect，涉及地球变暖。','建筑提供温暖且受控的生长环境，符合 greenhouse s1。'],['The greenhouse was an outdoor field with no walls, roof, or temperature control, exposed directly to winter frost.','The greenhouse was an enclosed, heated structure protecting plants from winter frost.','无墙无顶、完全暴露的田地不是温室。'],[[1,'A greenhouse is used to?',['grow plants in a controlled, often heated enclosure','store cars under the sea','measure the force of gravity'],0,'greenhouse s1 指培育植物的温室建筑。'],[2,'A greenhouse gas is a gas that?',['contributes to warming by trapping heat in the atmosphere','is grown in a glass building','turns into gravel'],0,'greenhouse s2 可作定语，描述与温室效应相关。'],[1,'Why regulate humidity in a greenhouse?',['plants may need controlled growing conditions','the structure must become a river','humidity measures a school grade'],0,'温室帮助控制植物生长条件。'],[2,'The greenhouse effect refers to?',['warming associated with heat retained in the atmosphere','a method for storing plants in a shed','the colour of greenhouse glass'],0,'greenhouse effect 指大气留热造成的变暖。']]);

})();
